/* 日商簿記2級の問題データ */
var BOKI = [
{id:"t1",group:"3級範囲",name:"簿記の基本・現金預金・商品売買",weeks:"案A 第1週 / 案B 第1週",ps:[
{t:"資本金の元入れ",q:"現金500,000を元入れして開業した。仕訳を示しなさい。",a:["(借)現金 500,000 (貸)資本金 500,000"],e:"元入れは純資産(資本金)の増加です。純資産は増えると貸方に書きます。"},
{t:"借入",q:"銀行から現金200,000を借り入れた。仕訳を示しなさい。",a:["(借)現金 200,000 (貸)借入金 200,000"],e:"借入金は負債です。負債が増えたので貸方に書きます。"},
{t:"備品の購入",q:"備品150,000を購入し、代金は現金で支払った。仕訳を示しなさい。",a:["(借)備品 150,000 (貸)現金 150,000"],e:"資産(備品)が増え、資産(現金)が減りました。資産の増加は借方、減少は貸方です。"},
{t:"商品の仕入(三分法)",q:"商品80,000を仕入れ、代金は掛けとした。仕訳を示しなさい。",a:["(借)仕入 80,000 (貸)買掛金 80,000"],e:"三分法では、商品を買ったら「仕入」(費用)で記録します。掛けで買ったときの相手は「買掛金」(負債)です。"},
{t:"商品の売上(三分法)",q:"商品120,000を売り上げ、代金は掛けとした。仕訳を示しなさい。",a:["(借)売掛金 120,000 (貸)売上 120,000"],e:"後で受け取る権利は「売掛金」(資産)、売ったら「売上」(収益)で貸方です。"},
{t:"他人振出の小切手",q:"商品60,000を売り上げ、代金は得意先振出の小切手で受け取った。仕訳を示しなさい。",a:["(借)現金 60,000 (貸)売上 60,000"],e:"他人(他社)が振り出した小切手は、すぐに換金できるので「現金」として扱います。"},
{t:"預金への預け入れ",q:"現金300,000を普通預金に預け入れた。仕訳を示しなさい。",a:["(借)普通預金 300,000 (貸)現金 300,000"],e:"資産から資産への移動です。増えた普通預金を借方、減った現金を貸方に書きます。"},
{t:"小切手の振出",q:"買掛金50,000を、小切手を振り出して支払った。仕訳を示しなさい。",a:["(借)買掛金 50,000 (貸)当座預金 50,000"],e:"自分が小切手を振り出すと「当座預金」が減ります。負債(買掛金)の減少は借方です。"},
{t:"現金の不足",q:"現金の帳簿残高は45,000だが、実際の有高は42,000だった。帳簿を実際の有高に合わせる仕訳を示しなさい。",a:["(借)現金過不足 3,000 (貸)現金 3,000"],e:"実際が少ないので、現金を3,000減らします。原因が分かるまでは「現金過不足」で処理します。"},
{t:"原因不明の不足額",q:"決算になっても、問9の不足額3,000の原因は分からなかった。仕訳を示しなさい。",a:["(借)雑損 3,000 (貸)現金過不足 3,000"],e:"原因不明の不足額は、決算で「雑損」(費用)にします。借方残高の現金過不足を、貸方で消します。"}
]},
{id:"t2",group:"3級範囲",name:"手形・貸付・固定資産・給料・税金・貸倒れ",weeks:"案A 第2週 / 案B 第2週",ps:[
{t:"約束手形",q:"(1)商品300,000を売り上げ、代金は約束手形で受け取った。\n(2)手形の期日に、手形代金が当座預金に入金された。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)受取手形 300,000 (貸)売上 300,000","(2)(借)当座預金 300,000 (貸)受取手形 300,000"],e:"手形を受け取ったら「受取手形」(資産)、取り立てて入金されたら受取手形を減らして当座預金を増やします。"},
{t:"貸付金と利息",q:"(1)取引先に500,000を貸し付け、小切手を振り出して渡した。\n(2)期日に、元本500,000と利息7,500を現金で受け取った。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)貸付金 500,000 (貸)当座預金 500,000","(2)(借)現金 507,500 (貸)貸付金 500,000 (貸)受取利息 7,500"],e:"貸したお金は「貸付金」(資産)です。利息は「受取利息」(収益)で貸方に書きます。現金は元本と利息の合計507,500です。"},
{t:"固定資産の購入",q:"備品400,000を購入し、据付費用20,000とともに現金で支払った。仕訳を示しなさい。",a:["(借)備品 420,000 (貸)現金 420,000"],e:"据付費用などの付随費用は、備品の取得原価に含めます。400,000+20,000=420,000です。"},
{t:"給料と預り金",q:"(1)給料300,000のうち、所得税の源泉徴収額20,000を差し引いた残額を現金で支払った。\n(2)後日、預かっていた所得税20,000を現金で納付した。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)給料 300,000 (貸)所得税預り金 20,000 (貸)現金 280,000","(2)(借)所得税預り金 20,000 (貸)現金 20,000"],e:"給料は総額300,000を費用にします。差し引いた20,000は、あとで国に納める預かり金(負債)です。"},
{t:"消費税(税抜方式)",q:"(1)商品100,000(税抜)を仕入れ、消費税10%とともに代金は掛けとした。\n(2)商品200,000(税抜)を売り上げ、消費税10%とともに代金は掛けとした。\n(3)決算で、消費税の納付額を計上した。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)仕入 100,000 (借)仮払消費税 10,000 (貸)買掛金 110,000","(2)(借)売掛金 220,000 (貸)売上 200,000 (貸)仮受消費税 20,000","(3)(借)仮受消費税 20,000 (貸)仮払消費税 10,000 (貸)未払消費税 10,000"],e:"税抜方式では、消費税を費用・収益にせず、仮払消費税・仮受消費税で記録します。決算では、仮受から仮払を引いた10,000が納付額(未払消費税)です。"},
{t:"貸倒れ",q:"前期に発生した売掛金40,000が、得意先の倒産で回収できなくなった。貸倒引当金の残高は30,000である。仕訳を示しなさい。",a:["(借)貸倒引当金 30,000 (借)貸倒損失 10,000 (貸)売掛金 40,000"],e:"前期以前の売掛金の貸倒れは、まず貸倒引当金を取り崩します。足りない10,000は貸倒損失(費用)にします。"},
{t:"当座借越",q:"当座預金の残高は100,000で、当座借越契約(限度額500,000)がある。買掛金150,000を、小切手を振り出して支払った。その後取引はなく決算日を迎えた。期中と決算時の仕訳を示しなさい。",a:["期中:(借)買掛金 150,000 (貸)当座預金 150,000","決算:(借)当座預金 50,000 (貸)当座借越 50,000"],e:"期中は当座預金勘定だけで処理し、残高がマイナス(貸方50,000)になっても構いません。決算で、貸方残高を当座借越(負債。借入金とすることもあります)に振り替えます。"}
]},
{id:"t3",group:"3級範囲",name:"決算整理・財務諸表",weeks:"案A 第3週 / 案B 第3週",ps:[
{t:"減価償却(定額法・間接法)",q:"取得原価600,000の備品(耐用年数6年、残存価額ゼロ)について、決算で減価償却を行う。仕訳を示しなさい(間接法)。",a:["(借)減価償却費 100,000 (貸)減価償却累計額 100,000"],e:"600,000÷6年=100,000です。間接法では、備品を直接減らさずに「減価償却累計額」を貸方に書きます。"},
{t:"貸倒引当金の設定",q:"決算で、売掛金800,000と受取手形200,000に2%の貸倒引当金を設定する。貸倒引当金の残高は5,000である(差額補充法)。仕訳を示しなさい。",a:["(借)貸倒引当金繰入 15,000 (貸)貸倒引当金 15,000"],e:"設定額=(800,000+200,000)×2%=20,000です。すでに5,000あるので、差額の15,000を繰り入れます。"},
{t:"売上原価の計算",q:"期首商品は50,000、当期の仕入は400,000、期末商品は70,000である。売上原価を「仕入」勘定で計算する仕訳を示し、売上原価を求めなさい。",a:["(借)仕入 50,000 (貸)繰越商品 50,000","(借)繰越商品 70,000 (貸)仕入 70,000","売上原価 380,000"],e:"期首商品を仕入に足し、期末商品を仕入から引きます。売上原価=50,000+400,000−70,000=380,000です。"},
{t:"費用・収益の繰延べと見越し",q:"決算日は3月31日である。\n(1)11月1日に、保険料12か月分60,000を支払っていた。前払分を計上する。\n(2)給料の未払いが40,000ある。\n(3)受取家賃のうち、24,000は次期分を受け取っていた。\n(4)受取利息の未収分が5,000ある。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)前払保険料 35,000 (貸)支払保険料 35,000","(2)(借)給料 40,000 (貸)未払給料 40,000","(3)(借)受取家賃 24,000 (貸)前受家賃 24,000","(4)(借)未収利息 5,000 (貸)受取利息 5,000"],e:"(1)保険料は11/1〜10/31の12か月分で、決算日(3/31)までに5か月経過、残り7か月分=60,000×7÷12=35,000が前払いです。(2)と(4)は、当期の費用・収益なのにまだ記録していない分を足します。(3)は、次期の収益を引きます。"},
{t:"現金過不足の決算処理",q:"決算で、現金過不足が(1)借方残高2,000、(2)貸方残高3,000のまま、原因が分からなかった。それぞれの仕訳を示しなさい。",a:["(1)(借)雑損 2,000 (貸)現金過不足 2,000","(2)(借)現金過不足 3,000 (貸)雑益 3,000"],e:"借方残高(不足)は「雑損」(費用)、貸方残高(過剰)は「雑益」(収益)にして、現金過不足を消します。"},
{t:"損益計算書の計算",q:"次の資料から、売上総利益、営業利益、当期純利益を求めなさい(法人税等は考えない)。\n・売上高 900,000 / 売上原価 540,000\n・給料 150,000 / 減価償却費 50,000 / 支払家賃 60,000\n・受取利息 10,000 / 支払利息 8,000",a:["売上総利益 360,000","営業利益 100,000","当期純利益 102,000"],e:"売上総利益=900,000−540,000=360,000。営業利益=360,000−(150,000+50,000+60,000)=100,000。当期純利益=100,000+受取利息10,000−支払利息8,000=102,000。"}
]},
{id:"k1",group:"工業簿記",name:"費目別計算・製造間接費・部門別計算",weeks:"案A 第5週 / 案B 第10週",ps:[
{t:"材料費(総平均法)",q:"月初材料100個(原価合計12,000)、当月仕入400個(購入原価合計52,000)、当月消費350個です。総平均法で消費額と月末材料の金額を求めなさい。",a:["消費額 44,800","月末材料 19,200"],e:"総平均単価=(12,000+52,000)÷(100+400)=128。消費350個×128=44,800、月末150個×128=19,200。"},
{t:"労務費(実際消費額)",q:"当月の賃金支払額は800,000、前月未払賃金は100,000、当月未払賃金は120,000です。賃金の当月実際消費額を求めなさい。",a:["820,000"],e:"当月支払800,000−前月未払100,000+当月未払120,000=820,000。支払額には前月分が含まれ、当月未払は当月の消費なので加えます。"},
{t:"予定賃率と賃率差異",q:"直接工の予定賃率は、1時間あたり1,600です。当月の作業時間は直接作業450時間、間接作業60時間です。問2の実際消費額をこの直接工の分として、(1)予定賃率による消費の仕訳と、(2)賃率差異の計上の仕訳を示しなさい。",a:["(1)(借)仕掛品 720,000 (借)製造間接費 96,000 (貸)賃金 816,000","(2)(借)賃率差異 4,000 (貸)賃金 4,000"],e:"直接作業450時間×1,600=720,000、間接作業60時間×1,600=96,000。予定消費816,000と実際820,000の差4,000は実際が多いので不利差異(借方)です。"},
{t:"製造間接費の予定配賦",q:"年間予算の製造間接費は24,000,000、年間予定直接作業時間は40,000時間です。当月の実際直接作業時間は3,200時間、製造間接費の実際発生額は1,990,000です。予定配賦率、予定配賦額、配賦差異(有利・不利を明記)を求めなさい。",a:["予定配賦率 600円/時間","予定配賦額 1,920,000","配賦差異 70,000(不利)"],e:"24,000,000÷40,000=600。3,200×600=1,920,000。実際1,990,000より70,000少ない(配賦不足)ので不利差異です。"},
{t:"製造間接費配賦差異の分析(公式法変動予算)",q:"月間の固定費予算1,200,000、変動費率は1時間あたり200、基準操業度は4,000時間です。当月の実際操業度は3,600時間、実際発生額は1,980,000です。予算差異と操業度差異を求めなさい。",a:["予算差異 60,000(不利)","操業度差異 120,000(不利)"],e:"予算許容額=200×3,600+1,200,000=1,920,000。予算差異=1,920,000−1,980,000=−60,000。固定費率=1,200,000÷4,000=300、操業度差異=(3,600−4,000)×300=−120,000。予定配賦率=変動費率200+固定費率300=500なので、配賦額=3,600×500=1,800,000。これと実際1,980,000の差180,000と一致します。"},
{t:"部門別計算(直接配賦法)",q:"製造部門は第1と第2、補助部門は動力と修繕です。部門費は第1製造400,000、第2製造300,000、動力100,000、修繕60,000です。動力の供給量は第1が600kWh、第2が400kWh、修繕の回数は第1が3回、第2が2回です。直接配賦法で補助部門費を配賦した後の、第1・第2製造部門費を求めなさい。",a:["第1製造部門 496,000","第2製造部門 364,000"],e:"動力100,000を600:400で、第1 60,000・第2 40,000。修繕60,000を3:2で、第1 36,000・第2 24,000。第1=400,000+60,000+36,000、第2=300,000+40,000+24,000。合計860,000が元の合計と一致します。"},
{t:"部門別計算(相互配賦法)",q:"部門費は第1製造400,000、第2製造300,000、動力100,000、修繕60,000です。動力部門の供給割合は修繕20%・第1製造50%・第2製造30%、修繕部門の供給割合は動力10%・第1製造45%・第2製造45%です。相互配賦法(第1次配賦で相互に配賦し、第2次配賦で製造部門へ直接配賦する簡便法)で、第1・第2製造部門費を求めなさい。",a:["第1製造部門 490,750","第2製造部門 369,250"],e:"第1次:動力→修繕20,000・第1 50,000・第2 30,000、修繕→動力6,000・第1 27,000・第2 27,000。第2次:修繕20,000を第1・第2に10,000ずつ、動力6,000を5:3で第1 3,750・第2 2,250。第1=400,000+50,000+27,000+10,000+3,750、第2=300,000+30,000+27,000+10,000+2,250。合計860,000で検算できます。"}
]},
{id:"k2",group:"工業簿記",name:"個別原価計算・総合原価計算",weeks:"案A 第6週 / 案B 第11週",ps:[
{t:"個別原価計算",q:"製造指図書#101の直接材料費は300,000、直接労務費は200,000、直接作業時間は100時間です。製造間接費は直接作業時間1時間あたり1,500円で配賦します。#101が完成し、売価900,000で掛け売りしました。製品への振替、売上、売上原価の仕訳を示しなさい。",a:["(借)製品 650,000 (貸)仕掛品 650,000","(借)売掛金 900,000 (貸)売上 900,000","(借)売上原価 650,000 (貸)製品 650,000"],e:"製造間接費の配賦額=100時間×1,500=150,000。製造原価=300,000+200,000+150,000=650,000です。製品の売上と売上原価は、必ずセットで仕訳します。"},
{t:"個別原価計算(仕損)",q:"製造指図書#301が全部仕損となり、新たに代品製造の指図書#301-2を発行しました。#301の製造原価は500,000、仕損品の評価額は60,000です。仕損は正常なもので、仕損費は#301-2に賦課します。この仕訳を示しなさい。",a:["(借)仕損品 60,000 (借)仕掛品(#301-2) 440,000 (貸)仕掛品(#301) 500,000"],e:"仕損費=500,000−60,000=440,000です。全部仕損では、旧指図書の製造原価から評価額を引いた額を、代品の指図書へ賦課します。いったん仕損費勘定を通して「(借)仕損品 60,000 (借)仕損費 440,000 (貸)仕掛品 500,000」「(借)仕掛品 440,000 (貸)仕損費 440,000」と書く方法もあり、どちらでも正解です。"},
{t:"単純総合原価計算(平均法)",q:"材料は始点投入です。月初仕掛品は200個(加工進捗50%)で、材料費40,000、加工費30,000です。当月は1,000個を投入し、材料費200,000、加工費276,000が発生しました。完成品は900個、月末仕掛品は300個(加工進捗40%)です。平均法で、完成品総合原価と月末仕掛品原価を求めなさい。",a:["完成品総合原価 450,000","月末仕掛品原価 96,000"],e:"材料費は始点投入なので数量で按分します。(40,000+200,000)÷(900+300)=200、完成900×200=180,000、月末300×200=60,000。加工費は完成品換算量が900+300×40%=1,020なので、(30,000+276,000)÷1,020=300、完成270,000、月末120×300=36,000です。完成品=180,000+270,000=450,000、月末=60,000+36,000=96,000。"},
{t:"単純総合原価計算(先入先出法)",q:"材料は始点投入です。月初仕掛品は200個(加工進捗50%)で、材料費38,000、加工費20,000です。当月は1,000個を投入し、材料費200,000、加工費276,000が発生しました。完成品は900個、月末仕掛品は300個(加工進捗40%)です。先入先出法で、完成品総合原価と月末仕掛品原価を求めなさい。",a:["完成品総合原価 438,000","月末仕掛品原価 96,000"],e:"先入先出法は当月投入分だけで単価を出します。材料は200,000÷1,000=200、月末300×200=60,000です。加工費の当月換算量は900+120−200×50%=920、276,000÷920=300、月末120×300=36,000です。月末=96,000、完成品=(38,000+20,000+200,000+276,000)−96,000=438,000。"},
{t:"正常仕損(度外視法)",q:"材料は始点投入で、月初仕掛品は100個(加工進捗40%)、材料費20,000、加工費12,000です。当月は900個を投入し、材料費180,000、加工費258,000が発生しました。完成品は700個、正常仕損は50個、月末仕掛品は250個(加工進捗60%)です。仕損は工程の終点で発生し、仕損品の評価額はありません。平均法・度外視法で、完成品総合原価と月末仕掛品原価を求めなさい。",a:["完成品総合原価 375,000","月末仕掛品原価 95,000"],e:"仕損が終点で発生するので、月末仕掛品(加工進捗60%)は仕損の発生点を通過せず、仕損費は完成品だけが負担します。材料は(20,000+180,000)÷(700+50+250)=200、月末250×200=50,000です。加工費の換算量は700+50+250×60%=900、(12,000+258,000)÷900=300、月末150×300=45,000です。月末=95,000、完成品=(32,000+438,000)−95,000=375,000(仕損費を含む)。"},
{t:"工程別総合原価計算(累加法)",q:"第1工程の完成品500個(原価400,000)を、すべて第2工程に始点投入しました。第2工程の月初仕掛品は100個(加工進捗50%)で、前工程費80,000、加工費20,000です。第2工程の当月加工費は82,000です。完成品は450個、月末仕掛品は150個(加工進捗40%)です。平均法で、第2工程の完成品総合原価と月末仕掛品原価を求めなさい。",a:["完成品総合原価 450,000","月末仕掛品原価 132,000"],e:"前工程費は始点投入なので数量で按分します。(80,000+400,000)÷(450+150)=800、完成450×800=360,000、月末150×800=120,000。加工費は換算量450+150×40%=510で、(20,000+82,000)÷510=200、完成90,000、月末60×200=12,000。完成品=360,000+90,000=450,000、月末=120,000+12,000=132,000。"},
{t:"組別総合原価計算",q:"組間接費(加工費)の当月発生額は600,000で、直接作業時間を基準にA組・B組へ配賦します。直接作業時間はA組1,500時間、B組1,000時間です。A組の組直接費(材料費)は500,000です。A組・B組への配賦額と、A組の当月製造費用を求めなさい。",a:["A組への配賦額 360,000","B組への配賦額 240,000","A組の当月製造費用 860,000"],e:"配賦率=600,000÷(1,500+1,000)=240円/時間。A組=1,500×240=360,000、B組=1,000×240=240,000。A組の当月製造費用=500,000+360,000=860,000です。"},
{t:"等級別総合原価計算",q:"完成品総合原価は1,350,000です。等価係数は1級品が1.0、2級品が0.6で、完成数量は1級品600個、2級品500個です。各等級の完成品原価と1個あたりの原価を求めなさい。",a:["1級品 900,000(1個 1,500)","2級品 450,000(1個 900)"],e:"積数は1級品600×1.0=600、2級品500×0.6=300で、比は2:1です。1,350,000を按分して、1級品900,000、2級品450,000。1個あたりは900,000÷600=1,500、450,000÷500=900です。"}
]},
{id:"k3",group:"工業簿記",name:"標準原価・直接原価・CVP・本社工場会計",weeks:"案A 第7週 / 案B 第12週",ps:[
{t:"直接材料費差異",q:"製品1個あたりの標準消費量は5kg、標準単価は1kgあたり200円です。当月の完成品は400個(月初・月末仕掛品なし)で、実際消費量は2,100kg、実際単価は1kgあたり195円でした。材料費差異を、価格差異と数量差異に分けて求めなさい。",a:["価格差異 10,500(有利)","数量差異 20,000(不利)","材料費差異 9,500(不利)"],e:"標準消費量=400個×5kg=2,000kg。価格差異=(200−195)×2,100kg=10,500。数量差異=(2,000−2,100)×200=−20,000。標準原価400,000と実際原価409,500の差−9,500と一致します。"},
{t:"直接労務費差異",q:"製品1個あたりの標準直接作業時間は3時間、標準賃率は1時間あたり1,000円です。当月の完成品は400個で、実際直接作業時間は1,230時間、実際賃率は1時間あたり1,020円でした。賃率差異と作業時間差異を求めなさい。",a:["賃率差異 24,600(不利)","作業時間差異 30,000(不利)"],e:"標準時間=400個×3時間=1,200時間。賃率差異=(1,000−1,020)×1,230時間=−24,600。作業時間差異=(1,200−1,230)×1,000=−30,000。標準1,200,000と実際1,254,600の差−54,600と一致します。"},
{t:"製造間接費差異",q:"基準操業度は月1,300直接作業時間、固定費予算は650,000、変動費率は1時間あたり500円です。標準直接作業時間は問2の1,200時間、実際直接作業時間は1,230時間、実際発生額は1,285,000でした。予算差異、能率差異、操業度差異を求めなさい(3分法)。",a:["予算差異 20,000(不利)","能率差異 30,000(不利)","操業度差異 35,000(不利)"],e:"標準配賦率=650,000÷1,300+500=1,000。予算許容額=500×1,230+650,000=1,265,000なので、予算差異=1,265,000−1,285,000=−20,000。能率差異=(1,200−1,230)×1,000=−30,000。操業度差異=(1,230−1,300)×500=−35,000(固定費率は650,000÷1,300=500)。合計−85,000は、標準配賦額1,200,000と実際1,285,000の差と一致します。"},
{t:"直接原価計算と全部原価計算",q:"販売単価は1,000、変動製造費は1個400、変動販売費は1個100、固定製造費は月200,000、固定販売費及び一般管理費は月120,000です。当月の生産量は1,000個、販売量は800個で、期首の在庫はありません。直接原価計算の営業利益と全部原価計算の営業利益を求め、差額の理由を説明しなさい。",a:["直接原価計算の営業利益 80,000","全部原価計算の営業利益 120,000","差額 40,000(理由:期末在庫200個に含まれる固定製造費40,000が、全部原価計算では次期に繰り延べられるため)"],e:"直接原価計算:売上800,000−変動売上原価320,000−変動販売費80,000=貢献利益400,000、固定費320,000を引いて80,000。全部原価計算:製造単価=400+200,000÷1,000=600、売上原価=800×600=480,000、売上総利益320,000から販売費及び一般管理費200,000を引いて120,000。差額は、期末在庫200個に含まれる固定製造費(200個×200=40,000)が、全部原価計算では次期に繰り延べられるためです。"},
{t:"CVP分析",q:"問4の資料(変動費は1個あたり500、固定費は合計320,000)で、貢献利益率、損益分岐点売上高、営業利益100,000を得るための売上高、売上高800,000のときの安全余裕率を求めなさい。",a:["貢献利益率 50%","損益分岐点売上高 640,000","目標売上高 840,000","安全余裕率 20%"],e:"貢献利益率=(1,000−500)÷1,000=50%。損益分岐点売上高=320,000÷0.5=640,000。目標売上高=(320,000+100,000)÷0.5=840,000。安全余裕率=(800,000−640,000)÷800,000=20%です。"},
{t:"本社工場会計",q:"工場の会計が独立している場合の、本社と工場の仕訳を示しなさい。\n(1)本社が材料400,000を掛けで購入し、工場に納入した。\n(2)本社が工場の賃金200,000を現金で支払った。\n(3)工場が完成品650,000を本社に引き渡した(製品は本社が管理する)。",a:["(1)本社:(借)工場 400,000 (貸)買掛金 400,000","(1)工場:(借)材料 400,000 (貸)本社 400,000","(2)本社:(借)工場 200,000 (貸)現金 200,000","(2)工場:(借)賃金 200,000 (貸)本社 200,000","(3)工場:(借)本社 650,000 (貸)仕掛品 650,000","(3)本社:(借)製品 650,000 (貸)工場 650,000"],e:"本社には「工場」勘定、工場には「本社」勘定を置き、貸借を互いに対応させます。内部の取引は、本社の「工場」と工場の「本社」が必ず同額で逆の関係になり、本社と工場を合算した財務諸表では相殺されます。(3)は製品勘定が本社にあるので、工場は仕掛品から直接本社へ引き渡したと記帳します。"}
]},
{id:"s1",group:"商業簿記",name:"収益認識・債権譲渡・固定資産・リース",weeks:"案A 第8週 / 案B 第4〜5週",ps:[
{t:"収益認識(複数の履行義務)",q:"商品と1年間の保守サービスを合わせて108,000で販売し、代金は現金で受け取りました。商品の独立販売価格は100,000、保守サービスの独立販売価格は20,000です。(1)販売時の仕訳と、(2)半年が経過した決算時の仕訳を示しなさい。",a:["(1)(借)現金 108,000 (貸)売上 90,000 (貸)契約負債 18,000","(2)(借)契約負債 9,000 (貸)役務収益 9,000"],e:"独立販売価格の比で按分します。商品=108,000×100÷120=90,000、保守=108,000×20÷120=18,000。保守サービスは1年かけて提供するので、半年分の9,000を決算で収益にします。"},
{t:"収益認識(リベート)",q:"商品500,000を掛けで販売しました。一定数量を超えると5%を返金する契約で、返金が見込まれます。販売時の仕訳を示しなさい。",a:["(借)売掛金 500,000 (貸)売上 475,000 (貸)返金負債 25,000"],e:"返金が見込まれる部分(500,000×5%=25,000)は売上にせず、返金負債にします。"},
{t:"手形の割引と不渡り",q:"受取手形600,000を銀行で割り引き、割引料12,000を差し引かれた手取額が当座預金に入金されました。その後、この手形が不渡りとなり、割引先から手数料3,000を含む603,000の償還請求を受け、当座預金から支払いました。それぞれの仕訳を示しなさい。",a:["割引時:(借)当座預金 588,000 (借)手形売却損 12,000 (貸)受取手形 600,000","不渡り時:(借)不渡手形 603,000 (貸)当座預金 603,000"],e:"手取額=600,000−12,000=588,000。不渡りでは、手形の額面に償還請求の費用3,000を加えた603,000を、手形の振出人に請求する債権として不渡手形勘定に計上します。"},
{t:"圧縮記帳(直接減額方式)",q:"国庫補助金1,000,000を現金で受け取りました。その後、機械装置4,000,000を現金で購入し、補助金に相当する額の圧縮記帳を行いました。決算で、定額法(耐用年数5年、残存価額ゼロ、期首に取得、間接法)で減価償却しました。補助金の受取時、購入時、圧縮記帳、決算の仕訳を示しなさい。",a:["受取時:(借)現金 1,000,000 (貸)国庫補助金受贈益 1,000,000","購入時:(借)機械装置 4,000,000 (貸)現金 4,000,000","圧縮記帳:(借)固定資産圧縮損 1,000,000 (貸)機械装置 1,000,000","決算:(借)減価償却費 600,000 (貸)機械装置減価償却累計額 600,000"],e:"圧縮後の取得原価は3,000,000で、償却額=3,000,000÷5=600,000です。圧縮記帳で、補助金の受贈益にかかる課税を先に延ばします。"},
{t:"固定資産の期中売却",q:"取得原価3,000,000の建物(定額法、耐用年数10年、残存価額ゼロ)を、当期首から4か月後に1,000,000で売却し、代金は後日受け取ります。前期末までの減価償却累計額は1,800,000です(間接法で記帳)。売却時の仕訳を示しなさい(当期分の減価償却は月割りで計上します)。",a:["(借)建物減価償却累計額 1,800,000 (借)減価償却費 100,000 (借)未収入金 1,000,000 (借)固定資産売却損 100,000 (貸)建物 3,000,000"],e:"年間償却額=3,000,000÷10=300,000で、当期分は300,000×4÷12=100,000です。売却時の帳簿価額=3,000,000−1,800,000−100,000=1,100,000なので、売却価額1,000,000との差100,000が売却損です。"},
{t:"リース取引(ファイナンス・リース)",q:"年額120,000を5年間、毎年末に現金で後払いするリース契約を結びました。リース料総額は600,000で、見積現金購入価額は540,000です。\n(1)利子込み法での契約時の仕訳\n(2)利子抜き法での契約時の仕訳\n(3)利子抜き法で第1回の支払い(利息は定額法で配分)と、決算時の減価償却(定額法、耐用年数5年、残存価額ゼロ)の仕訳",a:["(1)(借)リース資産 600,000 (貸)リース債務 600,000","(2)(借)リース資産 540,000 (貸)リース債務 540,000","(3)支払い:(借)リース債務 108,000 (借)支払利息 12,000 (貸)現金 120,000","(3)償却:(借)減価償却費 108,000 (貸)リース資産減価償却累計額 108,000"],e:"利子抜き法では、利息総額=600,000−540,000=60,000を5年で均等に配分し、年12,000です。償却額=540,000÷5=108,000です。"},
{t:"ソフトウェア",q:"自社利用目的のソフトウェアの制作費2,400,000を当座預金で支払いました(制作中)。その後、完成して利用を開始しました。決算(利用開始から8か月)で、5年間の定額法で償却しました。それぞれの仕訳を示しなさい(直接法)。",a:["制作中:(借)ソフトウェア仮勘定 2,400,000 (貸)当座預金 2,400,000","完成時:(借)ソフトウェア 2,400,000 (貸)ソフトウェア仮勘定 2,400,000","決算:(借)ソフトウェア償却 320,000 (貸)ソフトウェア 320,000"],e:"償却額=2,400,000÷5×8÷12=320,000です。制作中は仮勘定、利用開始でソフトウェアに振り替えて償却を始めます。"}
]},
{id:"s2",group:"商業簿記",name:"有価証券・引当金・外貨・税金・税効果・株主資本",weeks:"案A 第9週 / 案B 第6週",ps:[
{t:"売買目的有価証券(切放法)",q:"A社株式100株を1株5,000円で購入し、現金で支払いました。\n(1)購入時\n(2)決算時(時価は1株5,200円)\n(3)翌期に40株を1株5,300円で売却し現金を受け取ったとき(切放法)\nの仕訳を示しなさい。",a:["(1)(借)売買目的有価証券 500,000 (貸)現金 500,000","(2)(借)売買目的有価証券 20,000 (貸)有価証券評価益 20,000","(3)(借)現金 212,000 (貸)売買目的有価証券 208,000 (貸)有価証券売却益 4,000"],e:"期末の評価額は100株×5,200=520,000で、評価益20,000です。切放法では評価後の帳簿価額(5,200)が次期の原価になるため、売却40株の帳簿価額は40×5,200=208,000、売却額は40×5,300=212,000で、売却益は4,000です。"},
{t:"満期保有目的債券(償却原価法)",q:"額面1,000,000の社債を950,000で取得しました(満期まで5年、定額法)。取得から1年後の決算の仕訳を示しなさい。",a:["(借)満期保有目的債券 10,000 (貸)有価証券利息 10,000"],e:"償却額=(1,000,000−950,000)÷5年=10,000です。取得価額と額面の差を、満期までに少しずつ増やします。"},
{t:"その他有価証券",q:"B社株式を800,000で取得し、決算時の時価は880,000でした(全部純資産直入法)。決算時と、翌期首の洗替えの仕訳を示しなさい。",a:["決算時:(借)その他有価証券 80,000 (貸)その他有価証券評価差額金 80,000","翌期首:(借)その他有価証券評価差額金 80,000 (貸)その他有価証券 80,000"],e:"評価差額=880,000−800,000=80,000です。評価差額は損益にせず、純資産の部に直入します。翌期首には逆仕訳で洗い替えます。"},
{t:"貸倒引当金",q:"売掛金2,000,000(うち甲社分300,000は貸倒懸念債権)と受取手形1,000,000があります。貸倒引当金の残高は30,000です。一般債権には2%の貸倒実績率を使い、甲社分は担保の評価額100,000を除いた残額の50%を見込みます。決算の仕訳を示しなさい。",a:["(借)貸倒引当金繰入 124,000 (貸)貸倒引当金 124,000"],e:"一般債権=(3,000,000−300,000)×2%=54,000です。甲社分=(300,000−100,000)×50%=100,000です。合計154,000から、既存の残高30,000を引いた124,000を繰り入れます。"},
{t:"外貨建取引",q:"商品1,000ドルを掛けで輸出しました(取引日のレートは1ドル100円)。決算日のレートは1ドル103円、翌期の決済日のレートは1ドル101円で、代金は当座預金に入金されました。(1)取引時、(2)決算時、(3)決済時の仕訳を示しなさい。",a:["(1)(借)売掛金 100,000 (貸)売上 100,000","(2)(借)売掛金 3,000 (貸)為替差損益 3,000","(3)(借)当座預金 101,000 (借)為替差損益 2,000 (貸)売掛金 103,000"],e:"取引時=1,000ドル×100=100,000です。決算時は103円に換算し、差の3,000が為替差益です。決済時は101円で入金されるので、帳簿の103,000との差2,000が為替差損です。"},
{t:"法人税等と税効果会計",q:"中間納付した法人税等300,000(仮払法人税等)があり、決算で当期の法人税等が700,000と確定しました。また、貸倒引当金の繰入限度超過額が200,000あり(損金不算入)、法定実効税率は30%です。(1)法人税等の計上と(2)税効果の仕訳を示しなさい。",a:["(1)(借)法人税、住民税及び事業税 700,000 (貸)仮払法人税等 300,000 (貸)未払法人税等 400,000","(2)(借)繰延税金資産 60,000 (貸)法人税等調整額 60,000"],e:"未払法人税等=700,000−300,000=400,000です。繰延税金資産=200,000×30%=60,000で、将来の税金の前払いにあたります。"},
{t:"株主資本",q:"(1)株式1,000株を1株1,500円で発行し、払込金は当座預金に入金されました(資本金は会社法が認める最低限度額とします)。\n(2)株主総会で、繰越利益剰余金から1,000,000の配当を決議しました(配当額の10分の1を利益準備金に積み立てます)。\n(3)当期純利益2,000,000を振り替えました。\nそれぞれの仕訳を示しなさい。",a:["(1)(借)当座預金 1,500,000 (貸)資本金 750,000 (貸)資本準備金 750,000","(2)(借)繰越利益剰余金 1,100,000 (貸)未払配当金 1,000,000 (貸)利益準備金 100,000","(3)(借)損益 2,000,000 (貸)繰越利益剰余金 2,000,000"],e:"払込額の2分の1までを資本金にしないことができ、残りは資本準備金です。配当を決議すると、配当額の10分の1(100,000)を利益準備金に積み立てます。当期純利益は損益勘定から繰越利益剰余金に振り替えます。"}
]},
{id:"s3",group:"商業簿記",name:"決算・財務諸表・本支店",weeks:"案A 第10週 / 案B 第7週",ps:[
{t:"商品の棚卸減耗と評価損(三分法)",q:"期首商品80,000、当期仕入900,000です。期末の帳簿棚卸数量は200個(原価1個500円)、実地棚卸数量は190個、正味売却価額は1個480円です。売上原価を求める仕訳と、棚卸減耗損・商品評価損の仕訳を示しなさい(売上原価は「仕入」勘定で計算します)。",a:["(借)仕入 80,000 (貸)繰越商品 80,000","(借)繰越商品 100,000 (貸)仕入 100,000","(借)棚卸減耗損 5,000 (貸)繰越商品 5,000","(借)商品評価損 3,800 (貸)繰越商品 3,800"],e:"帳簿棚卸高=200×500=100,000。棚卸減耗損=(200−190)×500=5,000。商品評価損=(500−480)×190=3,800で、期末商品の貸借対照表価額は190×480=91,200です。"},
{t:"費用の繰延・見越し",q:"決算日は3月31日です。\n(1)10月1日に年間家賃(12か月分)240,000を支払いました。前払分の仕訳を示しなさい。\n(2)12月1日に4,000,000を年利率3%(利払いは年1回の11月30日)で借り入れました。未払利息の仕訳を示しなさい。",a:["(1)(借)前払家賃 120,000 (貸)支払家賃 120,000","(2)(借)支払利息 40,000 (貸)未払利息 40,000"],e:"家賃は10/1〜9/30の12か月分で、決算日(3/31)までに6か月経過、残り6か月分=240,000×6÷12=120,000が前払いです。利息は12/1〜3/31の4か月分=4,000,000×3%×4÷12=40,000を見越計上します。"},
{t:"減価償却",q:"取得原価1,200,000の備品(定額法、耐用年数8年、残存価額は取得原価の10%)の、当期の減価償却費と、前期末までに2年経過している場合の当期末の帳簿価額を求めなさい。",a:["当期の減価償却費 135,000","当期末の帳簿価額 795,000"],e:"年間償却額=1,200,000×(1−0.1)÷8=135,000。当期末の累計額=135,000×3年=405,000なので、帳簿価額=1,200,000−405,000=795,000です。"},
{t:"決算整理と財務諸表",q:"試算表(一部)は、次のとおりです。\n・売上 5,000,000\n・仕入(当期分) 3,200,000\n・繰越商品(期首) 300,000\n・給料 700,000\n・支払家賃 240,000(10月1日に12か月分を支払い)\n・備品 1,000,000 / 備品減価償却累計額 200,000\n・売掛金 1,000,000 / 貸倒引当金 20,000\n決算整理は、(a)期末商品棚卸高400,000、(b)備品は定額法(耐用年数5年、残存価額ゼロ)、(c)貸倒引当金は売掛金残高の3%を設定(差額補充法)、(d)家賃の前払いを決算日3月31日で計上、(e)給料の未払いが50,000です。\n売上原価、売上総利益、営業利益、貸借対照表の備品(帳簿価額)と売掛金(貸倒引当金控除後)を求めなさい。",a:["売上原価 3,100,000","売上総利益 1,900,000","営業利益 820,000","備品(帳簿価額) 600,000","売掛金(貸倒引当金控除後) 970,000"],e:"売上原価=300,000+3,200,000−400,000=3,100,000。売上総利益=5,000,000−3,100,000=1,900,000。販売費及び一般管理費=給料(700,000+50,000)+家賃(240,000−120,000)+減価償却費200,000(1,000,000÷5)+貸倒引当金繰入10,000(1,000,000×3%−20,000)=1,080,000。営業利益=1,900,000−1,080,000=820,000。備品の帳簿価額=1,000,000−(200,000+200,000)=600,000。売掛金=1,000,000−30,000=970,000。"},
{t:"本支店会計(商品の発送と利益の振替)",q:"(1)本店が支店に商品(原価)150,000を発送したとき、\n(2)支店が当期純利益80,000を計上し、本店に振り替えたとき\nの、本店と支店の仕訳をそれぞれ示しなさい。",a:["(1)本店:(借)支店 150,000 (貸)仕入 150,000","(1)支店:(借)仕入 150,000 (貸)本店 150,000","(2)支店:(借)損益 80,000 (貸)本店 80,000","(2)本店:(借)支店 80,000 (貸)損益 80,000"],e:"本店には「支店」勘定、支店には「本店」勘定を置き、貸借を逆にします。商品の発送では、本店が仕入を減らし、支店が仕入を増やします。支店の利益は本店の損益に入れます。"},
{t:"本支店会計(未達事項)",q:"決算時、本店の支店勘定は借方1,230,000、支店の本店勘定は貸方1,220,000でした。原因は、(a)本店が発送した商品60,000が支店に未達、(b)支店が本店の売掛金50,000を現金で回収したが、本店に未通知です。未達事項の整理仕訳(本店側・支店側)を示し、一致した残高を求めなさい。",a:["(a)支店:(借)仕入 60,000 (貸)本店 60,000","(b)本店:(借)支店 50,000 (貸)売掛金 50,000","一致した残高 1,280,000"],e:"本店の支店勘定=1,230,000+50,000=1,280,000。支店の本店勘定=1,220,000+60,000=1,280,000。未達は、「自分がまだ知らない取引」を自分の帳簿に記入することです。"}
]},
{id:"s4",group:"商業簿記",name:"合併・事業譲渡・連結会計",weeks:"案A 第10〜11週 / 案B 第8〜9週",ps:[
{t:"合併(吸収合併)",q:"A社がB社を吸収合併し、新株を交付しました。B社の諸資産の時価は2,000,000、諸負債の時価は800,000です。交付した株式の時価は1,500,000で、そのうち資本金に1,000,000を計上し、残りは資本準備金とします。A社の仕訳を示しなさい(パーチェス法)。",a:["(借)諸資産 2,000,000 (借)のれん 300,000 (貸)諸負債 800,000 (貸)資本金 1,000,000 (貸)資本準備金 500,000"],e:"純資産の時価=2,000,000−800,000=1,200,000。のれん=交付した株式の時価1,500,000−1,200,000=300,000です。交付した株式の時価を資本金と資本準備金に分けます。"},
{t:"事業譲渡",q:"事業を現金1,500,000で譲り受けました。譲り受けた諸資産の時価は2,000,000、諸負債の時価は800,000です。仕訳を示しなさい。",a:["(借)諸資産 2,000,000 (借)のれん 300,000 (貸)諸負債 800,000 (貸)現金 1,500,000"],e:"事業譲渡も、合併と同じ考え方です。のれん=支払対価1,500,000−1,200,000=300,000です。合併と違い、株式ではなく現金を払うので、貸方は現金になります。"},
{t:"のれんの償却",q:"問2で計上したのれんを、取得から期末まで1年(期首に取得)、定額法10年で償却します。決算の仕訳を示しなさい。",a:["(借)のれん償却 30,000 (貸)のれん 30,000"],e:"300,000÷10年=30,000です。のれんは無形固定資産として、直接法で記帳します。"},
{t:"資本連結(支配獲得日)",q:"P社がS社の株式の80%を960,000で取得して支配しました。取得日のS社の純資産は資本金500,000、利益剰余金500,000で、資産・負債の時価と帳簿価額は同じです。連結修正仕訳(投資と資本の相殺消去)を示しなさい。",a:["(借)資本金 500,000 (借)利益剰余金 500,000 (借)のれん 160,000 (貸)S社株式 960,000 (貸)非支配株主持分 200,000"],e:"S社の純資産=500,000+500,000=1,000,000。P社持分80%=800,000、のれん=960,000−800,000=160,000。非支配株主持分=1,000,000×20%=200,000です。借方と貸方の合計はどちらも1,160,000で一致します。"},
{t:"支配獲得後の連結修正",q:"問4の次の期で、\n(1)のれんを、取得から20年で定額法償却します。\n(2)S社の当期純利益は100,000です。\n(3)S社が50,000の配当を行い、P社はその80%を受け取りました。\nそれぞれの連結修正仕訳を示しなさい。",a:["(1)(借)のれん償却 8,000 (貸)のれん 8,000","(2)(借)非支配株主に帰属する当期純利益 20,000 (貸)非支配株主持分 20,000","(3)(借)受取配当金 40,000 (借)非支配株主持分 10,000 (貸)剰余金の配当 50,000"],e:"のれん償却=160,000÷20=8,000。非支配株主の持分は20%なので、当期純利益100,000×20%=20,000。配当50,000のうち、P社分は80%の40,000(受取配当金)、非支配株主分は20%の10,000です。"},
{t:"内部取引と未実現利益(ダウンストリーム)",q:"P社はS社に商品600,000を売り上げました。S社の期末商品には、このうち400,000が残っています。P社の売上総利益率は20%です。内部売上の相殺と、期末商品に含まれる未実現利益の消去の連結修正仕訳を示しなさい。",a:["(借)売上高 600,000 (貸)売上原価 600,000","(借)売上原価 80,000 (貸)商品 80,000"],e:"内部売上は、売上高と売上原価を同額で相殺します。未実現利益=期末商品400,000×20%=80,000で、P社が計上した利益なので、ダウンストリームでは全額を親会社株主が負担し、非支配株主には配分しません。"},
{t:"債権債務の相殺",q:"P社のS社に対する売掛金300,000(S社の買掛金300,000と同額)があり、P社はこの売掛金に対して2%の貸倒引当金を計上しています。連結修正仕訳を示しなさい。",a:["(借)買掛金 300,000 (貸)売掛金 300,000","(借)貸倒引当金 6,000 (貸)貸倒引当金繰入 6,000"],e:"債権と債務を同額で相殺し、その債権に設定した貸倒引当金(300,000×2%=6,000)も相殺します。"}
]},
{id:"d1",group:"本試験形式の大問",name:"第1問形式:仕訳5問セット(×3回)",weeks:"本試験の第1問(20点)対策。1セット15分が目安",ps:[
{t:"仕訳セットA",q:"次の取引の仕訳を示しなさい(勘定科目は適切なものを使うこと)。\n(1)取得原価1,200,000、減価償却累計額720,000(間接法で記帳)の備品を900,000で売却し、代金は翌月末に受け取ることにした。\n(2)得意先振出の約束手形500,000を銀行で割り引き、割引料8,000を差し引かれた手取金を当座預金とした。\n(3)前期に貸倒れとして処理した売掛金150,000のうち、60,000を現金で回収した。\n(4)新株2,000株を1株800円で発行し、全額が当座預金に払い込まれた。資本金は会社法が定める最低額とした。\n(5)売買目的で保有するA社株式1,000株(帳簿価額は1株700円)を、1株750円で売却し、代金は当座預金とした。",a:["(1)(借)未収入金 900,000 (借)備品減価償却累計額 720,000 (貸)備品 1,200,000 (貸)固定資産売却益 420,000","(2)(借)当座預金 492,000 (借)手形売却損 8,000 (貸)受取手形 500,000","(3)(借)現金 60,000 (貸)償却債権取立益 60,000","(4)(借)当座預金 1,600,000 (貸)資本金 800,000 (貸)資本準備金 800,000","(5)(借)当座預金 750,000 (貸)売買目的有価証券 700,000 (貸)有価証券売却益 50,000"],e:"(1)帳簿価額=1,200,000−720,000=480,000。売却額900,000との差420,000が売却益です。(2)手取金=500,000−8,000=492,000で、割引料は手形売却損とします。(3)償却済みの債権の回収は償却債権取立益です。(4)払込額=800×2,000=1,600,000。最低でも1/2を資本金にし、残りは資本準備金です。(5)売却額750,000−帳簿700,000=50,000が売却益です。"},
{t:"仕訳セットB",q:"次の取引の仕訳を示しなさい。\n(1)給料800,000を支給するにあたり、所得税の源泉徴収額60,000と社会保険料の従業員負担額40,000を控除し、残額を当座預金から支払った。\n(2)ファイナンス・リース取引で、機械(見積現金購入価額2,700,000)を契約し、引渡しを受けた。利子抜き法で処理する。\n(3)建物の改修工事1,000,000を小切手で支払った。このうち700,000は資本的支出、300,000は収益的支出である。\n(4)商品2,000ドルを掛けで輸入した。仕入時の為替レートは1ドル=110円である。\n(5)貸倒引当金の損金算入限度超過額200,000について、税効果会計を適用する(法定実効税率30%)。",a:["(1)(借)給料 800,000 (貸)所得税預り金 60,000 (貸)社会保険料預り金 40,000 (貸)当座預金 700,000","(2)(借)リース資産 2,700,000 (貸)リース債務 2,700,000","(3)(借)建物 700,000 (借)修繕費 300,000 (貸)当座預金 1,000,000","(4)(借)仕入 220,000 (貸)買掛金 220,000","(5)(借)繰延税金資産 60,000 (貸)法人税等調整額 60,000"],e:"(1)給料は総額で費用にし、控除分は預り金とします。(2)利子抜き法では見積現金購入価額でリース資産とリース債務を計上します。(3)価値を高める支出は資本的支出で建物、原状回復は修繕費です。(4)2,000×110=220,000。(5)200,000×30%=60,000を繰延税金資産とし、法人税等調整額(貸方)で処理します。"},
{t:"仕訳セットC",q:"次の取引の仕訳を示しなさい。\n(1)決算で、当期の法人税、住民税及び事業税が1,000,000と確定した。中間納付額400,000は仮払法人税等で処理している。\n(2)株主総会で、繰越利益剰余金を財源に1,000,000の配当が決議された。あわせて、会社法の規定による利益準備金100,000を積み立てる。\n(3)割り引いていた約束手形300,000が不渡りとなり、償還請求の費用5,000とともに小切手を振り出して支払った。\n(4)商品600,000を販売し、引き渡した。かねて受け取っていた手付金200,000(契約負債)を充当し、残額は掛けとした。\n(5)満期保有目的で、額面1,000,000の社債を期首に970,000で取得していた。満期は5年後で、償却原価法(定額法)を適用する。決算の仕訳を示しなさい。",a:["(1)(借)法人税、住民税及び事業税 1,000,000 (貸)仮払法人税等 400,000 (貸)未払法人税等 600,000","(2)(借)繰越利益剰余金 1,100,000 (貸)未払配当金 1,000,000 (貸)利益準備金 100,000","(3)(借)不渡手形 305,000 (貸)当座預金 305,000","(4)(借)契約負債 200,000 (借)売掛金 400,000 (貸)売上 600,000","(5)(借)満期保有目的債券 6,000 (貸)有価証券利息 6,000"],e:"(1)未払分=1,000,000−400,000=600,000。(2)配当と積立ての合計1,100,000を繰越利益剰余金から減らします。(3)手形額面に償還費用を加えた305,000が不渡手形です。(4)手付金は契約負債で、収益を認識する時に取り崩します。(5)(1,000,000−970,000)÷5年=6,000です。"}
]},
{id:"d2",group:"本試験形式の大問",name:"第4問形式:総合原価計算と標準原価計算",weeks:"本試験の第4問(28点)対策。合計22分が目安",ps:[
{t:"単純総合原価計算(平均法・正常減損)",m:12,q:"次の資料から、月末仕掛品原価と完成品原価、完成品の単位原価を求めなさい。平均法で、正常減損費は度外視法で処理する。\n・月初仕掛品 200個(加工進捗50%) 直接材料費120,000 加工費90,000\n・当月投入 1,000個 直接材料費980,000 加工費910,000\n・完成品 900個\n・月末仕掛品 200個(加工進捗50%)\n・正常減損 100個(工程の始点で発生)\n・直接材料は工程の始点で投入する。",a:["月末仕掛品原価 300,000","完成品原価 1,800,000","完成品単位原価 2,000"],e:"総額は材料1,100,000、加工費1,000,000です。正常減損は始点発生なので、完成品と月末仕掛品の両者に負担させます(度外視法では、減損を無視して換算量を計算し、月末仕掛品を求めてから差引きで完成品を求めます)。材料の完成品換算量=900+200=1,100で単価1,000、月末は200×1,000=200,000。加工費換算量=900+200×50%=1,000で単価1,000、月末は100×1,000=100,000。月末仕掛品=300,000、完成品=2,100,000−300,000=1,800,000、単位原価は1,800,000÷900=2,000です。"},
{t:"標準原価計算の差異分析",m:10,q:"製品1個あたりの標準は、直接材料2kg(1kg300円)、直接作業1.5時間(1時間800円)、製造間接費は直接作業時間を基準に配賦(基準操業度は月1,000時間、変動費率300円、固定費予算400,000)です。当月は600個を完成させました(仕掛品なし)。実績は、材料の消費1,250kg(実際単価295円)、直接作業940時間(実際賃率790円)、製造間接費の実際発生額700,000でした。\n(1)価格差異、数量差異\n(2)賃率差異、作業時間差異\n(3)製造間接費の予算差異、能率差異、操業度差異(3分法)\nを、有利か不利かをつけて答えなさい。",a:["価格差異 6,250(有利)","数量差異 15,000(不利)","賃率差異 9,400(有利)","作業時間差異 32,000(不利)","予算差異 18,000(不利)","能率差異 28,000(不利)","操業度差異 24,000(不利)"],e:"標準消費量=600×2=1,200kg、標準時間=600×1.5=900時間。価格差異=(300−295)×1,250=6,250(有利)。数量差異=(1,200−1,250)×300=−15,000(不利)。賃率差異=(800−790)×940=9,400(有利)。作業時間差異=(900−940)×800=−32,000(不利)。標準配賦率=300+400,000÷1,000=700。予算許容額=300×940+400,000=682,000なので予算差異=682,000−700,000=−18,000。能率差異=(900−940)×700=−28,000。操業度差異=(940−1,000)×400=−24,000。合計−70,000は、標準配賦額630,000と実際700,000の差と一致します。"}
]},
{id:"d3",group:"本試験形式の大問",name:"第5問形式:直接原価計算とCVP分析",weeks:"本試験の第5問(12点)対策。12分が目安",ps:[
{t:"直接原価計算・CVP・全部原価計算との差",m:12,q:"当月の資料です。販売単価2,000、変動製造費900/個、変動販売費100/個、固定製造費600,000、固定販売費及び一般管理費400,000。当月の生産量2,000個、販売量1,600個、期首在庫なし。\n(1)直接原価計算の営業利益\n(2)損益分岐点売上高\n(3)営業利益800,000を得るための売上高\n(4)安全余裕率\n(5)単価を1,800に下げた場合の損益分岐点販売量\n(6)全部原価計算の営業利益",a:["(1)営業利益 600,000","(2)損益分岐点売上高 2,000,000","(3)目標売上高 3,600,000","(4)安全余裕率 37.5%","(5)損益分岐点販売量 1,250個","(6)営業利益 720,000"],e:"変動費は1個1,000。(1)貢献利益=(2,000−1,000)×1,600=1,600,000、固定費合計1,000,000を引いて600,000。(2)貢献利益率50%なので1,000,000÷0.5=2,000,000。(3)(1,000,000+800,000)÷0.5=3,600,000。(4)売上高3,200,000なので(3,200,000−2,000,000)÷3,200,000=37.5%。(5)貢献利益は1個800なので1,000,000÷800=1,250個。(6)固定製造費は1個300、期末在庫400個に含まれる120,000だけ利益が増えて720,000です(売上3,200,000−売上原価1,920,000−販管費560,000でも一致)。"}
]},
{id:"d4",group:"本試験形式の大問",name:"第3問形式:決算整理と財務諸表",weeks:"本試験の第3問(20点)対策。20分が目安",ps:[
{t:"決算整理と損益計算書・貸借対照表",m:20,q:"決算整理前残高の一部と決算整理事項から、各金額を求めなさい。\n【残高】売掛金2,000,000 貸倒引当金10,000 繰越商品400,000 仕入6,000,000 売上9,000,000 建物5,000,000 建物減価償却累計額1,500,000 備品1,000,000 備品減価償却累計額360,000 給料1,500,000 保険料240,000\n【整理事項】\n(1)期末商品は帳簿棚卸高450,000、実地棚卸高440,000(棚卸減耗損は販売費及び一般管理費とする)。\n(2)売掛金に2%の貸倒引当金を差額補充法で設定する。\n(3)建物は耐用年数25年・残存価額ゼロの定額法、備品は償却率25%の定率法(間接法)。\n(4)保険料のうち80,000は前払分である。\n(5)給料の未払分が100,000ある。\n求めるもの:売上原価、貸倒引当金繰入、減価償却費、販売費及び一般管理費の合計、営業利益、貸借対照表の売掛金(純額)、商品、建物、備品、前払保険料、未払給料",a:["売上原価 5,950,000","貸倒引当金繰入 30,000","減価償却費 360,000","販売費及び一般管理費 2,160,000","営業利益 890,000","売掛金(純額) 1,960,000","商品 440,000","建物 3,300,000","備品 480,000","前払保険料 80,000","未払給料 100,000"],e:"売上原価=400,000+6,000,000−450,000=5,950,000(棚卸減耗損10,000は別に販管費)。繰入額=2,000,000×2%−10,000=30,000。建物の償却=5,000,000÷25=200,000、備品=(1,000,000−360,000)×25%=160,000、合計360,000。給料=1,500,000+100,000=1,600,000、保険料=240,000−80,000=160,000。販管費=1,600,000+160,000+30,000+360,000+10,000=2,160,000。売上総利益=9,000,000−5,950,000=3,050,000、営業利益=3,050,000−2,160,000=890,000。売掛金(純額)=2,000,000−40,000=1,960,000。建物=5,000,000−1,500,000−200,000=3,300,000。備品=640,000−160,000=480,000です。"}
]},
{id:"d5",group:"本試験形式の大問",name:"第2問形式:連結会計",weeks:"本試験の第2問(20点)対策。20分が目安",ps:[
{t:"連結財務諸表の金額計算",m:20,q:"P社は前期末にS社の株式の80%を880,000で取得して支配しました。取得時のS社の純資産は資本金600,000、利益剰余金400,000で、資産・負債の時価と帳簿価額は同じです。のれんは10年で定額法により償却します。\n当期のS社は、当期純利益150,000、配当50,000(P社は40,000を受け取った)です。P社は当期にS社へ商品500,000を売り上げ、S社の期末商品に200,000が残っています(P社の売上総利益率25%)。P社の売掛金とS社の買掛金に120,000の相殺すべき債権債務があります。\nP社の個別の利益剰余金は期末で2,000,000、売掛金800,000、商品700,000です。S社の売掛金は500,000、商品は600,000です。\n求めるもの:取得日ののれん、当期ののれん償却額、非支配株主に帰属する当期純利益、期末ののれん、期末の非支配株主持分、連結貸借対照表の売掛金、商品、利益剰余金",a:["取得日ののれん 80,000","のれん償却額 8,000","非支配株主に帰属する当期純利益 30,000","期末ののれん 72,000","非支配株主持分 220,000","売掛金 1,180,000","商品 1,250,000","利益剰余金 2,022,000"],e:"S社の純資産=1,000,000、P社持分800,000、のれん=880,000−800,000=80,000。償却額=80,000÷10=8,000。非支配株主に帰属する当期純利益=150,000×20%=30,000(のれん償却と、P社から売った商品の未実現利益はP社側の負担です)。期末のれん=72,000。非支配株主持分=200,000+30,000−10,000(配当50,000×20%)=220,000。売掛金=800,000+500,000−120,000=1,180,000。未実現利益=200,000×25%=50,000なので、商品=700,000+600,000−50,000=1,250,000。利益剰余金=2,000,000+(S社の取得後増加100,000×80%)−のれん償却8,000−未実現利益50,000=2,022,000です。"}
]},
{id:"m1",group:"模擬試験(90分・5大問)",name:"模擬試験 第1回",weeks:"全体で90分。本番と同じ順番で、通して解く",ps:[
{t:"第1問 仕訳5問",m:20,q:"次の取引の仕訳を示しなさい。\n(1)前期に販売した売掛金250,000が回収不能となった。貸倒引当金の残高は180,000ある。\n(2)帳簿価額500,000の自己株式を600,000で処分し、代金は当座預金とした。\n(3)期末に、その他有価証券(取得原価800,000)を時価900,000で評価する。全部純資産直入法で、法定実効税率は30%として税効果会計を適用する。\n(4)前期末に1ドル=105円で換算していた売掛金3,000ドルを、1ドル=108円で回収し、普通預金に入金した。\n(5)本店は、支店が本店の得意先から回収した売掛金200,000の連絡を受けた(本店の仕訳を示すこと)。",a:["(1)(借)貸倒引当金 180,000 (借)貸倒損失 70,000 (貸)売掛金 250,000","(2)(借)当座預金 600,000 (貸)自己株式 500,000 (貸)その他資本剰余金 100,000","(3)(借)その他有価証券 100,000 (貸)繰延税金負債 30,000 (貸)その他有価証券評価差額金 70,000","(4)(借)普通預金 324,000 (貸)売掛金 315,000 (貸)為替差益 9,000","(5)(借)支店 200,000 (貸)売掛金 200,000"],e:"(1)引当金で足りない分70,000が貸倒損失です。(2)処分価額と帳簿価額の差100,000は、その他資本剰余金です。(3)評価差額100,000のうち30%を繰延税金負債とし、残り70,000を評価差額金にします。(4)回収額=3,000×108=324,000、帳簿315,000との差9,000が為替差益です。(5)本店は、支店勘定の借方と売掛金の貸方で処理します。"},
{t:"第2問 株主資本等変動(純資産の計算)",m:15,q:"期首の純資産は、資本金5,000,000、資本準備金200,000、利益準備金400,000、繰越利益剰余金1,200,000です。期中に、①新株1,000株を1株1,500円で発行し全額払込み(資本金は最低額)、②繰越利益剰余金から800,000を配当し、利益準備金80,000を積み立てた。③当期純利益は1,500,000でした。期末の資本金、資本準備金、利益準備金、繰越利益剰余金、純資産合計を求めなさい。",a:["資本金 5,750,000","資本準備金 950,000","利益準備金 480,000","繰越利益剰余金 1,820,000","純資産合計 9,000,000"],e:"払込額=1,500×1,000=1,500,000。資本金は1/2の750,000、資本準備金も750,000の増加です。資本金=5,750,000、資本準備金=200,000+750,000=950,000。利益準備金=400,000+80,000=480,000。繰越利益剰余金=1,200,000−800,000−80,000+1,500,000=1,820,000。合計=9,000,000で、期首6,800,000+払込1,500,000−配当800,000+純利益1,500,000と一致します。"},
{t:"第3問 決算整理と財務諸表",m:20,q:"【残高】売掛金3,000,000 受取手形1,000,000 貸倒引当金50,000 繰越商品600,000 仕入8,000,000 売上12,000,000 備品2,000,000 備品減価償却累計額800,000 給料1,000,000 保険料360,000 売買目的有価証券500,000\n【整理事項】(1)期末商品は帳簿棚卸高700,000、実地棚卸高680,000(棚卸減耗損は販売費及び一般管理費)。(2)売上債権に3%の貸倒引当金を差額補充法で設定する。(3)備品は定額法(耐用年数5年、残存価額ゼロ)で償却する。(4)保険料のうち90,000は前払分である。(5)給料の未払分100,000を計上する。(6)売買目的有価証券の時価は540,000である。\n求めるもの:売上原価、貸倒引当金繰入、減価償却費、営業利益、経常利益、貸借対照表の売掛金等(純額)、商品、備品、有価証券、前払保険料",a:["売上原価 7,900,000","貸倒引当金繰入 70,000","減価償却費 400,000","営業利益 2,240,000","経常利益 2,280,000","売掛金等(純額) 3,880,000","商品 680,000","備品 800,000","有価証券 540,000","前払保険料 90,000"],e:"売上原価=600,000+8,000,000−700,000=7,900,000。引当金=(3,000,000+1,000,000)×3%=120,000、繰入=120,000−50,000=70,000。償却=2,000,000÷5=400,000。給料1,100,000+保険料270,000+繰入70,000+償却400,000+棚卸減耗損20,000=販管費1,860,000。売上総利益4,100,000−1,860,000=営業利益2,240,000。有価証券評価益40,000(営業外収益)を足して経常利益2,280,000。備品=2,000,000−(800,000+400,000)=800,000。売掛金等=4,000,000−120,000=3,880,000です。"},
{t:"第4問 部門別個別原価計算",m:17,q:"製造部門の第1製造部は450,000、第2製造部は300,000、補助部門の動力部は120,000、修繕部は80,000の部門費です。補助部門費は直接配賦法で配賦します。\n・動力の供給量:第1製造部600kWh、第2製造部400kWh\n・修繕の時間:第1製造部30時間、第2製造部20時間\n・製造部門の配賦基準:第1製造部は機械運転時間1,900時間、第2製造部は直接作業時間1,520時間\n(1)第1製造部と第2製造部の部門費合計\n(2)各製造部門の部門別配賦率(実際部門費÷実際配賦基準)\n(3)製品Aは第1製造部で機械運転800時間、第2製造部で直接作業600時間を使いました。製品Aへの製造間接費の配賦額と、直接材料費600,000、直接労務費400,000を加えた製造原価を求めなさい。",a:["第1製造部 570,000","第2製造部 380,000","配賦率 第1 300 / 第2 250","配賦額 390,000","製品Aの製造原価 1,390,000"],e:"動力部120,000は6:4で第1に72,000、第2に48,000。修繕部80,000は3:2で第1に48,000、第2に32,000。第1=450,000+72,000+48,000=570,000、第2=300,000+48,000+32,000=380,000。配賦率=570,000÷1,900=300、380,000÷1,520=250。製品Aの配賦額=300×800+250×600=390,000。製造原価=600,000+400,000+390,000=1,390,000です。"},
{t:"第5問 直接原価計算・CVP",m:18,q:"販売単価2,000、変動費(1個あたり)1,200、固定費2,400,000です。\n(1)貢献利益率\n(2)損益分岐点の売上高\n(3)営業利益1,000,000を得るための売上高\n(4)売上高7,500,000のときの営業利益",a:["(1)貢献利益率 40%","(2)損益分岐点売上高 6,000,000","(3)目標売上高 8,500,000","(4)営業利益 600,000"],e:"貢献利益は1個800(2,000−1,200)で、貢献利益率=800÷2,000=40%。(2)固定費2,400,000÷0.4=6,000,000。(3)(2,400,000+1,000,000)÷0.4=8,500,000。(4)7,500,000×0.4−2,400,000=600,000です。"}
]},
{id:"m2",group:"模擬試験(90分・5大問)",name:"模擬試験 第2回",weeks:"全体で90分。本番と同じ順番で、通して解く",ps:[
{t:"第1問 仕訳5問",m:20,q:"次の取引の仕訳を示しなさい。\n(1)決算で、当座預金勘定が貸方残高150,000になっていた(当座借越への振替をする)。\n(2)商品400,000をクレジットカード払いの条件で販売した。信販会社への手数料4%は販売時に計上する。\n(3)建物の建築代金6,000,000のうち、2,000,000を建設仮勘定として支払っていた。建物が完成して引渡しを受け、残額は当座預金で支払った。\n(4)国庫補助金1,000,000を受け取って取得した機械について、直接減額方式で圧縮記帳を行う(圧縮記帳の仕訳のみ)。\n(5)売買目的で保有するA社株式(帳簿価額800,000)を、決算で時価850,000に評価替えした。",a:["(1)(借)当座預金 150,000 (貸)当座借越 150,000","(2)(借)クレジット売掛金 384,000 (借)支払手数料 16,000 (貸)売上 400,000","(3)(借)建物 6,000,000 (貸)建設仮勘定 2,000,000 (貸)当座預金 4,000,000","(4)(借)固定資産圧縮損 1,000,000 (貸)機械 1,000,000","(5)(借)売買目的有価証券 50,000 (貸)有価証券評価益 50,000"],e:"(1)当座預金の貸方残高は、決算で当座借越(負債)に振り替えます。(2)手数料=400,000×4%=16,000です。(3)完成時に建設仮勘定を建物に振り替え、残額4,000,000を支払います。(4)補助金相当額を機械の帳簿価額から減らします。(5)時価が帳簿価額より50,000高いので、売買目的有価証券を増やし、有価証券評価益(収益)を貸方に計上します。"},
{t:"第2問 本支店会計",m:15,q:"本店の支店勘定は借方1,250,000、支店の本店勘定は貸方1,180,000です。未達事項は、(a)本店から支店へ発送した商品100,000が支店に未達、(b)支店が本店の得意先から回収した売掛金30,000が本店に未達でした。本店の売掛金は2,000,000、商品は800,000、支店の売掛金は700,000、商品は500,000です(いずれも未達事項の整理前)。\n(1)一致額\n(2)本店と支店の整理仕訳\n(3)本店・支店合併の貸借対照表の売掛金と商品",a:["(1)一致額 1,280,000","(2)本店:(借)支店 30,000 (貸)売掛金 30,000","(2)支店:(借)仕入 100,000 (貸)本店 100,000","(3)売掛金 2,670,000","(3)商品 1,400,000"],e:"本店:1,250,000+30,000=1,280,000。支店:1,180,000+100,000=1,280,000で一致します。売掛金=(2,000,000−30,000)+700,000=2,670,000。商品=800,000+500,000+未達商品100,000=1,400,000です。"},
{t:"第3問 決算整理と財務諸表",m:20,q:"【残高】受取手形800,000 売掛金2,200,000 貸倒引当金20,000 繰越商品500,000 仕入9,000,000 売上13,500,000 建物6,000,000 備品1,000,000 備品減価償却累計額400,000 給料1,300,000 保険料240,000 受取利息12,000\n【整理事項】(1)期末商品は帳簿棚卸数量200個(原価3,100円)、実地棚卸数量190個、正味売却価額2,900円。棚卸減耗損と商品評価損は、ともに売上原価に算入する。(2)売上債権に3%の貸倒引当金を差額補充法で設定する。(3)建物は当期首に取得したもので、耐用年数30年・残存価額ゼロの定額法、備品は償却率40%の定率法(前期末までの累計額は400,000)。(4)保険料のうち60,000は前払分である。\n求めるもの:売上原価、貸倒引当金繰入、減価償却費、営業利益、経常利益、備品の帳簿価額、商品",a:["売上原価 8,949,000","貸倒引当金繰入 70,000","減価償却費 440,000","営業利益 2,561,000","経常利益 2,573,000","備品 360,000","商品 551,000"],e:"売上原価=500,000+9,000,000−620,000=8,880,000。棚卸減耗損=10個×3,100=31,000、商品評価損=(3,100−2,900)×190=38,000で、合計8,949,000。繰入=(800,000+2,200,000)×3%−20,000=70,000。償却=建物200,000+備品(1,000,000−400,000)×40%=240,000=440,000。保険料=240,000−60,000=180,000。営業利益=13,500,000−8,949,000−(1,300,000+440,000+70,000+180,000)=2,561,000。経常利益=2,561,000+12,000=2,573,000です。商品=190×2,900=551,000、備品=1,000,000−400,000−240,000=360,000です。"},
{t:"第4問 組別総合原価計算",m:17,q:"A組とB組を製造しています。組間接費の製造間接費500,000は、直接労務費の比(A組300,000、B組200,000)で配賦します。A組の当月の直接材料費は600,000、直接労務費は300,000です。月初仕掛品は材料費60,000、加工費60,000、完成品は1,000個、月末仕掛品は200個(加工進捗50%)です。直接材料は始点で投入し、平均法で計算します。\n(1)A組への製造間接費の配賦額\n(2)A組の月末仕掛品原価、完成品原価、完成品の単位原価",a:["(1)配賦額 300,000","(2)月末仕掛品原価 170,000","(2)完成品原価 1,150,000","(2)単位原価 1,150"],e:"配賦額=500,000×300÷500=300,000。A組の加工費=300,000+300,000=600,000なので、材料費は60,000+600,000=660,000、加工費は60,000+600,000=660,000。材料の換算量=1,000+200=1,200で単価550、加工費の換算量=1,000+200×50%=1,100で単価600。月末仕掛品=200×550+100×600=170,000。完成品=1,320,000−170,000=1,150,000で、単位原価は1,150です。"},
{t:"第5問 CVP分析",m:18,q:"販売単価1,500、変動費(1個あたり)900、固定費1,800,000です。\n(1)損益分岐点の販売量\n(2)営業利益600,000を得る販売量\n(3)販売量5,000個のときの安全余裕率\n(4)販売量5,000個のときの営業レバレッジ(貢献利益÷営業利益)\n(5)広告費300,000を追加すると販売量が400個増える見込みです。営業利益の増減額は、増加ですか減少ですか。",a:["(1)損益分岐点販売量 3,000個","(2)目標販売量 4,000個","(3)安全余裕率 40%","(4)営業レバレッジ 2.5","(5)営業利益 60,000減少"],e:"貢献利益は1個600。(1)1,800,000÷600=3,000個。(2)(1,800,000+600,000)÷600=4,000個。(3)(5,000−3,000)÷5,000=40%。(4)貢献利益3,000,000÷営業利益1,200,000=2.5。(5)増える貢献利益400×600=240,000から広告費300,000を引いて、60,000減少です。"}
]},
{id:"m3",group:"模擬試験(90分・5大問)",name:"模擬試験 第3回",weeks:"全体で90分。本番と同じ順番で、通して解く。直前期の仕上げに",ps:[
{t:"第1問 仕訳5問",m:20,q:"次の取引の仕訳を示しなさい。\n(1)支払手形600,000の期日を延長し、新しい手形を振り出した。延長に伴う利息6,000は現金で支払った。\n(2)当期首に購入した自社利用目的のソフトウェア3,000,000について、決算で5年の定額法で償却する(直接法)。\n(3)前期に設定した製品保証引当金は100,000である。当期に、保証に基づく修理の費用120,000を現金で支払った。\n(4)その他資本剰余金800,000を取り崩して、繰越利益剰余金の欠損を填補した。\n(5)売買目的で社債(額面1,000,000)を額面100円につき98円で買い入れ、経過利息15,000とともに現金で支払った。",a:["(1)(借)支払手形 600,000 (借)支払利息 6,000 (貸)支払手形 600,000 (貸)現金 6,000","(2)(借)ソフトウェア償却 600,000 (貸)ソフトウェア 600,000","(3)(借)製品保証引当金 100,000 (借)製品保証費 20,000 (貸)現金 120,000","(4)(借)その他資本剰余金 800,000 (貸)繰越利益剰余金 800,000","(5)(借)売買目的有価証券 980,000 (借)有価証券利息 15,000 (貸)現金 995,000"],e:"(2)3,000,000÷5=600,000です。(3)引当金の残高100,000を超える20,000は費用です。(5)購入代金=1,000,000×98%=980,000で、経過利息は有価証券利息(借方)です。"},
{t:"第2問 連結(損益と純資産)",m:15,q:"P社は前期末にS社の株式の60%を1,000,000で取得し、支配しました。取得時のS社の純資産は、資本金1,000,000、利益剰余金500,000です。のれんは5年で定額法により償却します。\n当期のS社は、当期純利益200,000、配当100,000(P社は60,000を受け取った)です。S社はP社に商品800,000を売り上げ、P社の期末商品に300,000が残っています(S社の売上総利益率は20%)。P社の個別の当期純利益は700,000(配当の受取60,000を含む)、売上高は5,000,000、S社の売上高は3,000,000です。\n求めるもの:取得日ののれん、当期ののれん償却額、期末ののれん、連結の売上高、非支配株主に帰属する当期純利益、期末の非支配株主持分、連結の当期純利益、親会社株主に帰属する当期純利益",a:["取得日ののれん 100,000","のれん償却額 20,000","期末ののれん 80,000","連結売上高 7,200,000","非支配株主に帰属する当期純利益 56,000","非支配株主持分 616,000","連結当期純利益 760,000","親会社株主に帰属する当期純利益 704,000"],e:"S社の純資産1,500,000のP社持分=900,000、のれん=1,000,000−900,000=100,000。償却=100,000÷5=20,000。連結売上高=5,000,000+3,000,000−800,000=7,200,000。S社からP社への販売(アップストリーム)の未実現利益=300,000×20%=60,000で、これはS社の利益から引いて、非支配株主にも負担させます。非支配株主に帰属する当期純利益=(200,000−60,000)×40%=56,000。非支配株主持分=1,500,000×40%(600,000)+56,000−配当100,000×40%(40,000)=616,000。連結当期純利益=700,000+200,000−受取配当60,000−のれん償却20,000−未実現利益60,000=760,000。親会社株主に帰属する額は760,000−56,000=704,000です。"},
{t:"第3問 決算整理と財務諸表(税金まで)",m:20,q:"【残高】売掛金1,500,000 貸倒引当金8,000 繰越商品300,000 仕入5,000,000 売上7,500,000 建物4,000,000 リース資産600,000 給料900,000 仮払法人税等200,000\n【整理事項】(1)期末商品は350,000。(2)売掛金に2%の貸倒引当金を差額補充法で設定する。(3)建物は当期首に取得したもので、耐用年数20年・残存価額ゼロの定額法で償却する。リース資産(ファイナンス・リース、当期首に取得、利子抜き法)は6年・残存価額ゼロの定額法で償却する。(4)給料の未払分が80,000ある。(5)税引前当期純利益に30%の法人税等を計上する。\n求めるもの:売上原価、貸倒引当金繰入、減価償却費、営業利益、法人税等、当期純利益、未払法人税等、売掛金(純額)、リース資産の帳簿価額",a:["売上原価 4,950,000","貸倒引当金繰入 22,000","減価償却費 300,000","営業利益 1,248,000","法人税等 374,400","当期純利益 873,600","未払法人税等 174,400","売掛金(純額) 1,470,000","リース資産 500,000"],e:"売上原価=300,000+5,000,000−350,000=4,950,000。繰入=1,500,000×2%−8,000=22,000。償却=4,000,000÷20+600,000÷6=200,000+100,000=300,000。給料=900,000+80,000=980,000。営業利益=7,500,000−4,950,000−(980,000+22,000+300,000)=1,248,000。法人税等=1,248,000×30%=374,400、当期純利益=873,600、未払=374,400−200,000=174,400。売掛金(純額)=1,500,000−30,000=1,470,000。リース資産=600,000−100,000=500,000です。"},
{t:"第4問 工程別総合原価計算(累加法)",m:17,q:"第1工程は、当月に3,000,000の費用がかかり、1,000個が完成して第2工程に引き渡しました(仕掛品はなし)。第2工程は、前工程費を始点で投入し、当月の加工費は1,800,000、完成品は800個、月末仕掛品は200個(加工進捗50%)です(月初仕掛品なし)。\n(1)第1工程の完成品の単位原価\n(2)第2工程の月末仕掛品原価、完成品原価、完成品の単位原価",a:["(1)単位原価 3,000","(2)月末仕掛品原価 800,000","(2)完成品原価 4,000,000","(2)単位原価 5,000"],e:"第1工程の単位原価=3,000,000÷1,000=3,000。第2工程の前工程費は始点投入なので換算量は800+200=1,000で、単価3,000。加工費の換算量=800+200×50%=900で、単価1,800,000÷900=2,000。月末仕掛品=200×3,000+100×2,000=800,000。完成品=(3,000,000+1,800,000)−800,000=4,000,000で、単位原価は5,000です。"},
{t:"第5問 標準原価計算(製造間接費差異)",m:18,q:"製品1個あたりの標準直接作業時間は3時間です。製造間接費の基準操業度は月2,000時間、固定費予算は1,000,000、変動費率は1時間あたり300円です。当月は600個を完成させました(仕掛品なし)。実際の直接作業時間は1,850時間、製造間接費の実際発生額は1,500,000でした。\n(1)標準配賦率\n(2)予算差異、変動費能率差異、固定費能率差異、操業度差異(4分法)\n(3)製造間接費の差異の合計",a:["(1)標準配賦率 800","(2)予算差異 55,000(有利)","(2)変動費能率差異 15,000(不利)","(2)固定費能率差異 25,000(不利)","(2)操業度差異 75,000(不利)","(3)差異の合計 60,000(不利)"],e:"固定費率=1,000,000÷2,000=500で、標準配賦率=500+300=800。標準時間=600×3=1,800時間。予算許容額=300×1,850+1,000,000=1,555,000なので、予算差異=1,555,000−1,500,000=55,000(有利)。変動費能率差異=(1,800−1,850)×300=−15,000、固定費能率差異=(1,800−1,850)×500=−25,000。操業度差異=(1,850−2,000)×500=−75,000。合計=55,000−15,000−25,000−75,000=−60,000で、標準配賦額1,440,000と実際1,500,000の差と一致します。"}
]},
{id:"g",group:"総合問題",name:"総合問題(製造原価報告書・連結貸借対照表)",weeks:"案A 第12〜14週 / 案B 第13〜14週",ps:[
{t:"総合① 製造原価報告書と売上総利益",q:"次の資料から、当期の材料費、労務費、当期総製造費用、当期製品製造原価、売上原価、売上総利益を求めなさい。\n・期首材料 100,000 / 当期材料仕入 700,000 / 期末材料 150,000\n・賃金の当期支払額 500,000 / 前期未払額 50,000 / 当期未払額 70,000\n・経費(当期発生額) 150,000\n・期首仕掛品 200,000 / 期末仕掛品 250,000\n・期首製品 300,000 / 期末製品 350,000\n・売上高 1,800,000",a:["材料費 650,000","労務費 520,000","当期総製造費用 1,320,000","当期製品製造原価 1,270,000","売上原価 1,220,000","売上総利益 580,000"],e:"材料費=100,000+700,000−150,000=650,000。労務費=500,000−50,000+70,000=520,000。総製造費用=650,000+520,000+150,000=1,320,000。製品製造原価=1,320,000+200,000−250,000=1,270,000。売上原価=300,000+1,270,000−350,000=1,220,000。売上総利益=1,800,000−1,220,000=580,000。"},
{t:"総合② 連結貸借対照表",q:"P社はS社の株式の80%を960,000で取得し、支配しました。支配獲得日の貸借対照表は次のとおりです(S社の資産・負債の時価は帳簿価額と同じ)。連結貸借対照表の各金額を求めなさい。\n・諸資産 P社 4,000,000 / S社 1,800,000\n・S社株式 P社 960,000\n・諸負債 P社 2,000,000 / S社 800,000\n・資本金 P社 1,500,000 / S社 500,000\n・利益剰余金 P社 1,460,000 / S社 500,000",a:["諸資産 5,800,000","のれん 160,000","資産合計 5,960,000","諸負債 2,800,000","資本金 1,500,000","利益剰余金 1,460,000","非支配株主持分 200,000"],e:"諸資産=4,000,000+1,800,000。のれん=960,000−(1,000,000×80%)=160,000。非支配株主持分=1,000,000×20%=200,000。S社株式と、S社の資本金・利益剰余金は相殺して消えます。貸借の合計は、どちらも5,960,000で一致します。"}
]}
];
var BOKI_DM = { t1: 2, t2: 3, t3: 3, k1: 5, k2: 6, k3: 6, s1: 3, s2: 3, s3: 4, s4: 3, g: 25, d1: 15, d2: 22, d3: 12, d4: 20, d5: 20, m1: 18, m2: 18, m3: 18 };
BOKI.forEach(function (u) { u.dm = BOKI_DM[u.id] || 5; if (/^m\d$/.test(u.id)) u.mock = true; });
/* 本試験の配点: 第1問20点・第2問20点・第3問20点・第4問28点・第5問12点(合計100点、合格は70点以上) */
BOKI.forEach(function (u) { if (u.mock) u.ps.forEach(function (p, i) { p.pt = [20, 20, 20, 28, 12][i]; }); });

var BOKI_W = {"t1": ["元入れの貸方を売上などの収益にしがち。資本金は収益ではなく、出資を受けた純資産。覚え方は「現金が増えるから借方、元手の資本金は貸方」と動きで言えるようにしておく。", "借入金を資産と取り違え、借方に書く誤りが多い。現金は増えるが、返す義務が生じる。覚え方は「借りた現金は借方、返す義務の借入金は貸方」とセットで言う。借金は負債。", "備品を「備品費」などの費用にする誤りが多い。長く使う物は資産として計上する。覚え方は「物が増えたら借方、払った現金は貸方」と、お金と物の動きを一つずつ順に確認する。", "三分法では商品勘定でなく仕入(費用)を使う点を忘れやすい。掛けの相手は買掛金(負債)。覚え方は「買ったら仕入が借方、掛けなら買掛金が貸方」と、相手科目まで言い切る。", "売上と売掛金の借貸を逆にしがち。売掛金は後で受け取る権利で資産、売上は収益。覚え方は「売って代金の権利は借方、稼ぎは貸方」と、仕入の逆向きの仕訳として考えると間違えにくい。", "他人振出の小切手を当座預金や受取手形にする誤りが多い。すぐ換金できる通貨代用証券なので現金扱い。覚え方は「他人振出の小切手は、受け取ったら現金」。自社が振り出すと当座預金が減る。", "普通預金と現金の借貸を逆に書きやすい。資産同士の移動で、増えた方が借方、減った方が貸方。覚え方は「預金が増えたなら借方、減った現金は貸方」。仕訳は、先に増減を決めてから書く。", "小切手を振り出したのに、現金を貸方にしがち。自社が振り出すと当座預金が減る。他人振出の小切手の受取りは現金なので逆。覚え方は「自分で振り出したら当座預金を貸方」。", "不足なのに現金過不足を貸方に置く誤りが多い。実際が少ないと現金は減るので貸方で、相手の現金過不足が借方。覚え方は「足りないなら現金を貸方、過不足は借方」。不足なら現金を減らす。", "原因不明の不足を雑益にしたり、現金過不足の借貸を逆にしたりしがち。借方残高を消すので貸方に書く。覚え方は「不足は雑損(費用)、過剰は雑益(収益)」と対で暗記する。"], "t2": ["約束手形の受取りを売掛金や当座預金にしがち。手形債権は受取手形で、期日の入金時に貸方で減らす。覚え方は「受け取ったら受取手形が借方、取り立てて入金されたら貸方」。", "利息を貸付金に含めて貸方1本にする誤りが多い。利息は受取利息(収益)で別に計上し、現金は元本と利息の合計。覚え方は「現金は合算、貸方は元本と利息に分ける」。利息は収益。", "据付費用などの付随費用を別の費用にして、備品を400,000のままにする誤りが多い。使える状態にするまでの費用は取得原価に含める。覚え方は「付随費用は原価に足す」。", "給料を手取額280,000で費用計上する誤りが多い。費用は総額で、天引き分は所得税預り金(負債)。納付時は預り金を借方で消す。覚え方は「給料は総額、天引きは預り金」。", "税抜方式でも仕入と売上は税抜額にし、消費税を費用・収益にしない点が要。決算の相殺と未払額の算出を忘れやすい。覚え方は「受けた税から払った税を引いた差が未払消費税」。", "前期以前の売掛金の貸倒れで、全額を貸倒損失にする誤りが多い。まず貸倒引当金を取り崩し、足りない分だけ損失。覚え方は「引当金が先、不足が損失」。当期発生分は全額損失。", "期中から当座借越勘定を使う誤りが多い。本問は期中は当座預金が貸方残(マイナス)のままで処理し、決算で当座借越へ振り替える。覚え方は「期中は当座預金、決算で借越へ」。"], "t3": ["間接法で備品を直接減らす誤りが多い。備品はそのままにし、減価償却累計額を貸方に書く。覚え方は「間接法は備品に触れず累計額を貸方」。直接法は備品そのものを貸方で減らす。", "設定額20,000をそのまま繰り入れる誤りが多い。差額補充法では残高5,000を差し引いた差額だけを繰り入れる。覚え方は「必要額から今ある残高を引いた差額が繰入」。", "期首と期末商品の仕訳の向きを逆にしやすい。期首は仕入に足し、期末は仕入から引く。覚え方は「期首は仕入へ送る、期末は仕入から戻す」。売上原価は「期首+仕入−期末」。", "前払分を12か月分そのまま計上したり、前払と未払・前受を取り違えたりしがち。残月数は決算日から数える。覚え方は「費用の次期分は前払、収益の次期分は前受、当期の未計上は未払・未収」。", "借方残高と貸方残高で雑損と雑益を逆にしやすい。借方残高は不足なので雑損(費用)、貸方残高は過剰なので雑益(収益)。覚え方は「不足は損、過剰は益」と、残高の側で決める。", "営業利益と当期純利益を混同しやすい。受取利息や支払利息は営業外なので、営業利益には含めない。覚え方は「総利益から販管費を引いて営業利益、営業外を加減して純利益」。"], "s1": ["総額108,000を独立販売価格の比で按分せず、100,000と20,000をそのまま使う誤りが多い。保守分は契約負債とし、提供に応じて収益にする。覚え方は「価格の比で割り、未提供分は負債」。", "返金が見込まれる部分も売上に含める誤りが多い。返金負債は負債で、その分は売上から差し引く。覚え方は「戻すと見込む分は売上にせず返金負債、売掛金は全額で計上」と覚える。", "割引料を手形売却損にする点と、不渡り時に額面だけを不渡手形にする誤りに注意。償還請求の手数料も含めた請求額で計上する。覚え方は「不渡りは額面に費用を足した請求額」。", "圧縮損を忘れたり、償却を圧縮前の4,000,000で計算したりしがち。償却の基礎は圧縮後の帳簿価額。覚え方は「補助金分を先に圧縮し、残った3,000,000で償却」。", "期中売却で当期分の償却を忘れ、前期末の簿価で損益を出す誤りが多い。売却日まで月割りで償却してから、売却価額と比べる。覚え方は「売却日までの償却を済ませて簿価を出す」。", "利子込み法と利子抜き法で計上額を取り違えやすい。込みはリース料総額600,000、抜きは見積現金購入価額540,000で、差額が利息。覚え方は「抜きなら現金価額、利息は期間で配分」。", "制作中のソフトウェア仮勘定を使わず、いきなりソフトウェアにしがち。償却は利用開始後の月数で計算する。覚え方は「作っている間は仮勘定、使い始めてから償却」。償却は月割り。"], "s2": ["切放法では評価後の価額が次期の原価になる点を忘れ、当初の5,000で売却益を出す誤りが多い。覚え方は「切放しは評価後の時価が新しい原価」。洗替法は当初原価に戻す。売却益は新原価との差。", "差額50,000を一度に計上する誤りが多い。償却原価法は満期までの年数で割り、毎期有価証券利息に加える。覚え方は「額面との差を年数で割って毎期の利息」。年数で割ると覚える。", "その他有価証券の評価差額を損益(評価益)にする誤りが多い。全部純資産直入法では評価差額金に入れ、翌期首に洗い替える。覚え方は「その他は損益でなく純資産へ直入」。", "一般債権の合計から貸倒懸念債権を除き忘れたり、担保額を引かずに率を掛けたりしがち。覚え方は「一般債権は全体から甲社を除き、懸念債権は担保を引いてから率を掛ける」。", "決算時と決済時のレートを混同しやすい。決算で換算替えした帳簿価額103,000と、決済額101,000の差が決済時の差損益。覚え方は「決算で再評価、決済で帳簿との差」。", "法人税等を未払全額で計上し、仮払を忘れる誤りが多い。中間納付分は貸方で消す。繰延税金資産は一時差異に税率を掛ける。覚え方は「確定額から納付済を引くと未払」。確定額から納付済を引く。", "資本金の最低額は払込額の2分の1で、残りは資本準備金。配当の積立ては配当額の10分の1を利益準備金にし、未払配当金とは別に計上する。覚え方は「払込みは半分、配当は10分の1を準備金へ」。"], "s3": ["棚卸減耗損は原価で数量差、評価損は実地数量に単価差を掛ける。帳簿数量で評価損を出す誤りが多い。覚え方は「減耗損は原価と数量差、評価損は実地で単価差」。数量差か単価差かを分ける。", "前払分は残った月数を数え、見越しは経過した月数を数える。12か月分や借入期間の全部を機械的に使う誤りが多い。覚え方は「払った家賃は残り、借入利息は経過した月数」。", "残存価額10%を忘れて取得原価全額で割る誤りが多い。償却基礎額は取得原価の90%で、帳簿価額は経過年数(当期を含め3年)分を引く。覚え方は「原価×(1-残存率)÷年数」。", "販管費に前払・未払の調整、償却費、貸倒引当金繰入を入れ忘れる誤りが多い。覚え方は「整理事項(a)〜(e)を一つずつ処理してから利益を出す」。売上原価は期首+仕入-期末。", "本店と支店で貸借を同じ向きにしてしまう。本店は支店勘定、支店は本店勘定を使い、貸借は逆になる。覚え方は「本店が借方なら支店は貸方」と、本店と支店を必ず対にして書く。", "未達事項をどちらの帳簿に記入するか迷いやすい。自分が知らない取引を、自分の帳簿に後から記帳する。覚え方は「相手の出来事を自分が知らなければ自分で追記」。整理後は残高が一致する。"], "s4": ["のれんを簿価や株式の発行額と混同する誤りが多い。交付した株式の時価が対価で、時価の純資産との差。覚え方は「払った対価から受け取る時価純資産を引くとのれん」。時価で比べると覚える。", "合併の仕訳と混同し、貸方に資本金を置きがち。事業譲渡は現金などの支払なので資本金は出ない。覚え方は「対価が現金なら貸方は現金、株式なら資本金」。払う対価で貸方が決まる。", "のれんは直接法で、貸方をのれん勘定にするのを忘れがち。取得年数と償却年数も混同しやすい。覚え方は「のれん÷償却年数で毎期同額、貸方はのれん」。償却額は費用(のれん償却)。", "のれんを全部純資産の100%で計算する誤りが多い。持分比率分と取得対価の差がのれん、非支配分は純資産×20%。覚え方は「親は持分まで、残りは非支配株主持分」。非支配は持分比率で決まる。", "のれん償却を非支配株主に配分したり、配当を全額受取配当金にしたりしがち。非支配株主分は純利益と配当の20%。覚え方は「親分の配当は受取配当金、非支配分は持分の減少」。", "ダウンストリームの未実現利益を非支配株主に配分する誤りが多い。親から子への販売は全額を親が負担。覚え方は「期末残高×利益率、親売りなら非支配は関係なし」。売り手が親か子かで決まる。", "債権債務を相殺するだけで終え、貸倒引当金の調整を忘れる誤りが多い。覚え方は「債権を消したら、その債権に設定した貸倒引当金と繰入も消す」。債権・引当金・繰入が動く。"], "k1": ["総平均法は月初在庫も含めた全体で単価を出す点を忘れがち。先入先出法や移動平均法と混同しやすい。覚え方は「総平均=月初+仕入の合計÷合計数量」で、月末は残り数量×同単価。", "支払額をそのまま消費額にしてしまう誤りが多い。覚え方は「消費=支払−前月未払+当月未払」で、前月分は引き、当月未払は足す。未払は『後で払う分も今月の消費』と考える。", "予定賃率では直接工の間接作業時間も予定消費に含める点、差異の借貸の向きで迷う。覚え方は「実際が予定より多ければ不利で借方差異」。直接は仕掛品、間接は製造間接費。", "配賦差異の有利・不利が逆になりやすい。覚え方は「予定配賦額−実際発生額」で、マイナスなら配賦不足で不利。予定配賦率は予算÷予定時間、掛けるのは実際時間と覚える。", "固定費率を基準操業度で割る点と、予算許容額に実際操業度を使う点を取り違えやすい。覚え方は「予算差異=許容額−実際」「操業度差異=(実際−基準)×固定費率」で、実際が基準未満なら不利。", "直接配賦法では補助部門どうしの用役を無視し、製造部門の比だけで按分する。分母に他の補助部門の量を入れる誤りが多い。覚え方は「補助は製造部門へ直行」で、最後に合計が一致するか検算。", "第2次配賦は、第1次で受け入れた補助部門費だけを製造部門へ配賦する。補助部門どうしへ再配賦したり、元の全額を配り直したりする誤りが多い。覚え方は「1次は相互、2次は製造部門へ直行」。"], "k2": ["製品への振替額に製造間接費の配賦額を入れ忘れる誤りが多い。覚え方は「直接費+間接費配賦=製造原価」。売上は売価、売上原価は原価で、同額にしない。仕掛品→製品→売上原価の流れ。", "仕損品の評価額を引き忘れ、仕損費を500,000のままにする誤りが多い。覚え方は「仕損費=旧指図書の原価−評価額」で、仕損品は借方に別立て。本問は指示により、仕損費を代品の指図書へ賦課する。", "平均法では月初仕掛品の原価・数量も当月分とひとまとめにして按分する。始点投入の材料は数量、加工費は完成品換算量で割る点を混同しやすい。覚え方は「材料は進捗度ではなく数量」。", "先入先出法では月初仕掛品が先に完成すると考え、単価は当月投入分だけで出す点を忘れがち。覚え方は「FIFOは月初から先に完成」。加工費の換算量は完成+月末−月初の進捗分で、完成品は差引き。", "終点で発生する仕損費の負担先を誤りやすい。覚え方は「仕損の発生点を通過した在庫だけが負担」。月末仕掛品の進捗が発生点に届かなければ、仕損費は全額完成品の負担となる。", "本問のように前工程費が始点投入なら、進捗度を掛けず数量で按分する点を間違えやすい。覚え方は「前工程費は始点投入の材料と同じ扱い」。月初の前工程費は分子に加え、加工費だけ換算量で割る。", "組直接費は各組へ直課し、組間接費だけを配賦基準で配賦する。直接費まで按分に含めてしまう誤りが出やすい。配賦率は両組の総時間で割り、A組の当月製造費用は直課分に配賦額を足す。", "按分の基準を数量ではなく積数(数量×等価係数)にしなければならない点を忘れがち。覚え方は「等級別は積数で按分」。1個あたり原価は、等級の原価を等級の数量で割る。"], "k3": ["価格差異に実際数量、数量差異に標準単価を使う点を取り違えやすい。覚え方は「価格は実際数量・数量は標準単価」。標準消費量は完成品数×単位標準量。実際が多ければ不利。", "賃率差異は実際時間、作業時間差異は標準賃率で計算する点を取り違えやすい。覚え方は「賃率は実際時間・時間は標準賃率」で、材料費差異と同じ構造。標準時間は生産量×単位標準時間。", "能率差異は(標準時間−実際時間)に標準配賦率(変動費率+固定費率)を掛け、操業度差異は(実際−基準)に固定費率を掛ける点を誤りがち。覚え方は「予算=許容額、能率=標準との差、操業度=基準との差」。", "固定製造費を期間費用にするか製品原価にするかが差の本質。覚え方は「在庫が増えれば全部原価の利益が大きい」(減れば逆)。差額=期末在庫の固定製造費−期首在庫の固定製造費。", "損益分岐点や目標売上高では、固定費だけでなく目標利益も加えて貢献利益率で割る点を忘れやすい。覚え方は「(固定費+目標利益)÷貢献利益率」。安全余裕率は売上高を分母にとる。", "本社と工場の勘定の向きを取り違えやすい。覚え方は「本社側は工場、工場側は本社」で、貸借が必ず逆になる。製品を本社が管理する場合、工場は製品でなく仕掛品から引き渡す。"], "d2": ["始点発生の正常減損を月末仕掛品の負担に含めるかで迷い、換算量に減損数量を加える誤りが多い。覚え方は「始点減損は完成・月末が分担、度外視は減損を無視して計算」。検算は総額の合計。", "引き算の向きを誤り有利・不利が逆になりやすい。覚え方は「標準−実際、プラスなら有利」。ただし操業度差異は(実際−基準)×固定費率で、基準未満なら不利。価格は実際数量、数量は標準単価、能率は標準配賦率。"], "d3": ["在庫の固定製造費の扱いで、全部原価計算の利益を小さく見積る誤りが多い。覚え方は「期末在庫の固定製造費は次期へ繰り延べられ、利益が増える」。損益分岐点は貢献利益率で、価格変更後は貢献利益を再計算する。"], "g": ["賃金の未払額の加減算を逆にしたり、総製造費用と製品製造原価を混同しやすい。覚え方は「材料→労務→経費で総製造費用、+期首仕掛品−期末仕掛品で製品製造原価」。売上原価は製品の増減で調整する。", "のれんの計算に、非支配株主分を含めた全体の資本を使う誤りが多い。覚え方は「のれん=取得価額−(S社資本×持分割合)」で、非支配株主持分は資本×20%。投資と資本は相殺。"], "d1": ["(1)売却代金の未収分は売掛金でなく未収入金。(2)割引料は手形売却損で、手取金(借方・当座預金)は額面から割引料を引いた額。(4)資本金は払込額の1/2が最低額。「半分は資本金、残りは資本準備金」と覚える。(5)売却額と帳簿価額の差が損益。", "(1)源泉所得税や社会保険料は費用にせず預り金。給料は総額で借方。(2)利子抜き法は見積現金購入価額、利子込み法はリース料総額で計上。(3)価値を高める分は資本的支出で建物、原状回復分は修繕費。(5)資産の繰延税金資産は借方、法人税等調整額は反対側に置く。", "(1)中間納付分の仮払法人税等を差し引き忘れやすい。(2)積み立てる利益準備金も繰越利益剰余金から減らす。(3)不渡手形は償還費用も含めた額。(4)手付金は契約負債。(5)償却額は額面と取得価額の差額÷満期までの期間。"], "d4": ["棚卸減耗損を売上原価とするか販管費とするかは問題文の指示で決まる。本問は販管費で、帳簿と実地の差。備品の定率法は取得原価でなく期首帳簿価額に償却率を掛ける。前払保険料と未払給料は費用を調整する。求める科目を順に書き出すとよい。"], "d5": ["よく間違う点は、親会社から子会社への販売(ダウンストリーム)の未実現利益を、非支配株主にも負担させること。この場合は全額を親会社の利益から引く。のれん償却も親会社側の負担。子会社の取得後の利益増加には、持分割合を掛けて取り込む。"], "m1": ["(1)引当金で足りない額だけ貸倒損失。全額を損失にしがち。(2)自己株式処分差益は損益でなくその他資本剰余金。(3)評価差額は税効果で繰延税金負債を引いた残りが評価差額金。(4)為替は期末換算額との差。", "よく間違う点は、新株発行の払込額を全部資本金にすること。最低は1/2。配当時の利益準備金積立も繰越利益剰余金から減らす。検算は、期首純資産+払込+純利益−配当で合計に一致するか。", "棚卸減耗損の扱いを問題文で確認。ここは販管費で売上原価に入れない。引当金の対象は受取手形と売掛金の合計。有価証券の評価益は営業外収益で、営業利益には入れず経常利益で加える。備品は期首累計額に当期償却を足す。", "よく間違う点は、補助部門費の配賦基準と製造部門の配賦基準を混同すること。直接配賦法は補助部門間のやり取りを無視し、製造部門だけに按分する。部門ごとに配賦率を出し、各製品の使用時間にそれぞれ掛ける。", "貢献利益率=(単価−変動費)÷単価。損益分岐点売上高は固定費÷貢献利益率で、固定費を売上高で割らないこと。目標利益は固定費に足してから割ると覚える。"], "m2": ["(1)当座預金の貸方残高は当座借越へ振替。(2)クレジット売掛金は手数料控除後の額で、手数料は販売時に支払手数料。(3)建設仮勘定は完成時に建物へ振替。(4)圧縮損は直接減額方式。(5)評価替えは時価−帳簿価額=50,000の評価益。", "未達事項の整理は、どちら側の帳簿に未記入かを見分けるのが核心。商品の未達は受け取る側で仕入、売掛金の回収未達は本店側で支店勘定。両勘定の一致額を検算し、合併BSでは内部取引を消す。", "棚卸減耗損は帳簿数量と実地数量の差に原価を掛け、商品評価損は実地数量に原価と正味売却価額の差を掛ける。評価損の数量を帳簿数量にしがち。定率法は期首帳簿価額に率を掛け、当期首取得の建物は1年分を償却する。", "組間接費は先に配賦して各組の加工費に足してから計算に入る。平均法は月初仕掛品と当月分を合算。始点投入の材料は仕掛品も100%、加工費は進捗度。材料と加工費で換算量が違う点に注意。", "貢献利益は単価から変動費を引いたもの(固定費は引かない)。目標利益は固定費に利益を足して貢献利益で割る。安全余裕率は(実績−損益分岐点)÷実績。(5)は増える貢献利益と追加の固定費を比べる増分思考で判断する。"], "m3": ["(1)手形の更改は旧手形を消し新手形を立て、利息は別に支払う。(2)ソフトウェアは取得原価÷年数。(3)引当金を超える分だけ費用。(5)社債の経過利息は有価証券利息を借方に計上し、取得原価には含めない。", "よく間違う点は、子会社が売ったアップストリームの未実現利益を親のみに負担させること。子会社の利益から引き、非支配株主にも持分を負担させる。親の個別利益に含まれる受取配当は連結で消す。", "よく間違う点は、仮払法人税等を差し引かず、法人税等の全額を未払法人税等にすること。本問は税引前利益に税率を掛け、そこから仮払分を引く。ファイナンス・リース資産は本問ではリース期間6年で償却し、期首取得なら1年分。", "累加法は第1工程の完成品原価が第2工程の前工程費になる。前工程費は始点投入で仕掛品も100%、加工費は進捗度で換算量が違う。月初仕掛品がなければ先入先出法と平均法の差は出ない。", "差異分析は、実際時間と標準時間のどちらを基準にするかが肝心。予算差異は実際時間の予算許容額から実際発生額を引く。能率差異は標準時間との差、操業度差異は基準操業度との差。符号は有利と不利で整理。"]};
BOKI.forEach(function (u) { var w = BOKI_W[u.id]; if (w) u.ps.forEach(function (p, i) { if (w[i]) p.w = w[i]; }); });

(function () {
  var N = {
    b: ["3級の範囲", "3級で習う内容です。2級は3級の内容が前提なので、2級の試験でも出ます。3級が不安なときの土台づくりに使ってください。"],
    a: ["2級 商業簿記", "2級の商業簿記の問題です。"],
    x: ["2級 工業簿記", "2級の工業簿記の問題です。"],
    m: ["本試験形式", "本番と同じ形式・配点の問題です。"]
  };
  var MAP = { t1: "b", t2: "b", t3: "b", k1: "x", k2: "x", k3: "x", s1: "a", s2: "a", s3: "a", s4: "a", d1: "m", d2: "m", d3: "m", d4: "m", d5: "m", m1: "m", m2: "m", m3: "m", g: "m" };
  BOKI.forEach(function (u) { var k = MAP[u.id]; if (k) { u.lv = N[k][0]; u.lvn = N[k][1]; u.lvc = k; } });
  var X = { s1: [2], s4: [0, 1] };
  Object.keys(X).forEach(function (id) { BOKI.filter(function (u) { return u.id === id; })[0].ps.forEach(function (p, i) { if (X[id].indexOf(i) >= 0) p.lvx = "この問題は、現行の2級の出題範囲外(1級相当)の可能性があります。解けなくても気にしすぎないでください。"; }); });
})();

// おすすめの順番: 3級の範囲 → 工業簿記(点が取りやすい) → 商業簿記。連結会計(s4・d5)は最後にまとめず、途中に挟んで並行して進める。
