var BOKI_V = {"t1": {"0": [{"q": "現金800,000を元入れして開業した。仕訳を示しなさい。", "a": ["(借)現金 800,000 (貸)資本金 800,000"], "e": "元入れは純資産(資本金)の増加です。純資産は増えると貸方に書きます。"}, {"q": "現金350,000を元入れして開業した。仕訳を示しなさい。", "a": ["(借)現金 350,000 (貸)資本金 350,000"], "e": "元入れは純資産(資本金)の増加です。純資産は増えると貸方に書きます。"}], "1": [{"q": "銀行から現金300,000を借り入れた。仕訳を示しなさい。", "a": ["(借)現金 300,000 (貸)借入金 300,000"], "e": "借入金は負債です。負債が増えたので貸方に書きます。"}, {"q": "銀行から現金450,000を借り入れた。仕訳を示しなさい。", "a": ["(借)現金 450,000 (貸)借入金 450,000"], "e": "借入金は負債です。負債が増えたので貸方に書きます。"}], "2": [{"q": "備品240,000を購入し、代金は現金で支払った。仕訳を示しなさい。", "a": ["(借)備品 240,000 (貸)現金 240,000"], "e": "資産(備品)が増え、資産(現金)が減りました。資産の増加は借方、減少は貸方です。"}, {"q": "備品90,000を購入し、代金は現金で支払った。仕訳を示しなさい。", "a": ["(借)備品 90,000 (貸)現金 90,000"], "e": "資産(備品)が増え、資産(現金)が減りました。資産の増加は借方、減少は貸方です。"}], "3": [{"q": "商品130,000を仕入れ、代金は掛けとした。仕訳を示しなさい。", "a": ["(借)仕入 130,000 (貸)買掛金 130,000"], "e": "三分法では、商品を買ったら「仕入」(費用)で記録します。掛けで買ったときの相手は「買掛金」(負債)です。"}, {"q": "商品65,000を仕入れ、代金は掛けとした。仕訳を示しなさい。", "a": ["(借)仕入 65,000 (貸)買掛金 65,000"], "e": "三分法では、商品を買ったら「仕入」(費用)で記録します。掛けで買ったときの相手は「買掛金」(負債)です。"}], "4": [{"q": "商品180,000を売り上げ、代金は掛けとした。仕訳を示しなさい。", "a": ["(借)売掛金 180,000 (貸)売上 180,000"], "e": "後で受け取る権利は「売掛金」(資産)、売ったら「売上」(収益)で貸方です。"}, {"q": "商品95,000を売り上げ、代金は掛けとした。仕訳を示しなさい。", "a": ["(借)売掛金 95,000 (貸)売上 95,000"], "e": "後で受け取る権利は「売掛金」(資産)、売ったら「売上」(収益)で貸方です。"}], "5": [{"q": "商品90,000を売り上げ、代金は得意先振出の小切手で受け取った。仕訳を示しなさい。", "a": ["(借)現金 90,000 (貸)売上 90,000"], "e": "他人(他社)が振り出した小切手は、すぐに換金できるので「現金」として扱います。"}, {"q": "商品45,000を売り上げ、代金は得意先振出の小切手で受け取った。仕訳を示しなさい。", "a": ["(借)現金 45,000 (貸)売上 45,000"], "e": "他人(他社)が振り出した小切手は、すぐに換金できるので「現金」として扱います。"}], "6": [{"q": "現金400,000を普通預金に預け入れた。仕訳を示しなさい。", "a": ["(借)普通預金 400,000 (貸)現金 400,000"], "e": "資産から資産への移動です。増えた普通預金を借方、減った現金を貸方に書きます。"}, {"q": "現金250,000を普通預金に預け入れた。仕訳を示しなさい。", "a": ["(借)普通預金 250,000 (貸)現金 250,000"], "e": "資産から資産への移動です。増えた普通預金を借方、減った現金を貸方に書きます。"}], "7": [{"q": "買掛金70,000を、小切手を振り出して支払った。仕訳を示しなさい。", "a": ["(借)買掛金 70,000 (貸)当座預金 70,000"], "e": "自分が小切手を振り出すと「当座預金」が減ります。負債(買掛金)の減少は借方です。"}, {"q": "買掛金120,000を、小切手を振り出して支払った。仕訳を示しなさい。", "a": ["(借)買掛金 120,000 (貸)当座預金 120,000"], "e": "自分が小切手を振り出すと「当座預金」が減ります。負債(買掛金)の減少は借方です。"}], "8": [{"q": "現金の帳簿残高は60,000だが、実際の有高は56,000だった。帳簿を実際の有高に合わせる仕訳を示しなさい。", "a": ["(借)現金過不足 4,000 (貸)現金 4,000"], "e": "実際が少ないので、現金を4,000減らします。原因が分かるまでは「現金過不足」で処理します。"}, {"q": "現金の帳簿残高は38,000だが、実際の有高は33,000だった。帳簿を実際の有高に合わせる仕訳を示しなさい。", "a": ["(借)現金過不足 5,000 (貸)現金 5,000"], "e": "実際が少ないので、現金を5,000減らします。原因が分かるまでは「現金過不足」で処理します。"}], "9": [{"q": "決算になっても、現金過不足勘定の借方に残っている現金の不足額4,000の原因は分からなかった。仕訳を示しなさい。", "a": ["(借)雑損 4,000 (貸)現金過不足 4,000"], "e": "原因不明の不足額は、決算で「雑損」(費用)にします。借方残高の現金過不足を、貸方で消します。"}, {"q": "決算になっても、現金過不足勘定の借方に残っている現金の不足額5,000の原因は分からなかった。仕訳を示しなさい。", "a": ["(借)雑損 5,000 (貸)現金過不足 5,000"], "e": "原因不明の不足額は、決算で「雑損」(費用)にします。借方残高の現金過不足を、貸方で消します。"}]}, "t2": {"0": [{"q": "(1)商品450,000を売り上げ、代金は約束手形で受け取った。\n(2)手形の期日に、手形代金が当座預金に入金された。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)受取手形 450,000 (貸)売上 450,000", "(2)(借)当座預金 450,000 (貸)受取手形 450,000"], "e": "手形を受け取ったら「受取手形」(資産)、取り立てて入金されたら受取手形を減らして当座預金を増やします。"}, {"q": "(1)商品280,000を売り上げ、代金は約束手形で受け取った。\n(2)手形の期日に、手形代金が当座預金に入金された。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)受取手形 280,000 (貸)売上 280,000", "(2)(借)当座預金 280,000 (貸)受取手形 280,000"], "e": "手形を受け取ったら「受取手形」(資産)、取り立てて入金されたら受取手形を減らして当座預金を増やします。"}], "1": [{"q": "(1)取引先に600,000を貸し付け、小切手を振り出して渡した。\n(2)期日に、元本600,000と利息9,000を現金で受け取った。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)貸付金 600,000 (貸)当座預金 600,000", "(2)(借)現金 609,000 (貸)貸付金 600,000 (貸)受取利息 9,000"], "e": "貸したお金は「貸付金」(資産)です。利息は「受取利息」(収益)で貸方に書きます。現金は元本と利息の合計609,000です。"}, {"q": "(1)取引先に400,000を貸し付け、小切手を振り出して渡した。\n(2)期日に、元本400,000と利息6,000を現金で受け取った。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)貸付金 400,000 (貸)当座預金 400,000", "(2)(借)現金 406,000 (貸)貸付金 400,000 (貸)受取利息 6,000"], "e": "貸したお金は「貸付金」(資産)です。利息は「受取利息」(収益)で貸方に書きます。現金は元本と利息の合計406,000です。"}], "2": [{"q": "備品500,000を購入し、据付費用30,000とともに現金で支払った。仕訳を示しなさい。", "a": ["(借)備品 530,000 (貸)現金 530,000"], "e": "据付費用などの付随費用は、備品の取得原価に含めます。500,000+30,000=530,000です。"}, {"q": "備品250,000を購入し、据付費用15,000とともに現金で支払った。仕訳を示しなさい。", "a": ["(借)備品 265,000 (貸)現金 265,000"], "e": "据付費用などの付随費用は、備品の取得原価に含めます。250,000+15,000=265,000です。"}], "3": [{"q": "(1)給料400,000のうち、所得税の源泉徴収額30,000を差し引いた残額を現金で支払った。\n(2)後日、預かっていた所得税30,000を現金で納付した。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)給料 400,000 (貸)所得税預り金 30,000 (貸)現金 370,000", "(2)(借)所得税預り金 30,000 (貸)現金 30,000"], "e": "給料は総額400,000を費用にします。差し引いた30,000は、あとで国に納める預かり金(負債)です。"}, {"q": "(1)給料250,000のうち、所得税の源泉徴収額15,000を差し引いた残額を現金で支払った。\n(2)後日、預かっていた所得税15,000を現金で納付した。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)給料 250,000 (貸)所得税預り金 15,000 (貸)現金 235,000", "(2)(借)所得税預り金 15,000 (貸)現金 15,000"], "e": "給料は総額250,000を費用にします。差し引いた15,000は、あとで国に納める預かり金(負債)です。"}], "4": [{"q": "(1)商品150,000(税抜)を仕入れ、消費税10%とともに代金は掛けとした。\n(2)商品300,000(税抜)を売り上げ、消費税10%とともに代金は掛けとした。\n(3)決算で、消費税の納付額を計上した。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)仕入 150,000 (借)仮払消費税 15,000 (貸)買掛金 165,000", "(2)(借)売掛金 330,000 (貸)売上 300,000 (貸)仮受消費税 30,000", "(3)(借)仮受消費税 30,000 (貸)仮払消費税 15,000 (貸)未払消費税 15,000"], "e": "税抜方式では、消費税を費用・収益にせず、仮払消費税・仮受消費税で記録します。決算では、仮受から仮払を引いた15,000が納付額(未払消費税)です。"}, {"q": "(1)商品80,000(税抜)を仕入れ、消費税10%とともに代金は掛けとした。\n(2)商品250,000(税抜)を売り上げ、消費税10%とともに代金は掛けとした。\n(3)決算で、消費税の納付額を計上した。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)仕入 80,000 (借)仮払消費税 8,000 (貸)買掛金 88,000", "(2)(借)売掛金 275,000 (貸)売上 250,000 (貸)仮受消費税 25,000", "(3)(借)仮受消費税 25,000 (貸)仮払消費税 8,000 (貸)未払消費税 17,000"], "e": "税抜方式では、消費税を費用・収益にせず、仮払消費税・仮受消費税で記録します。決算では、仮受から仮払を引いた17,000が納付額(未払消費税)です。"}], "5": [{"q": "前期に発生した売掛金60,000が、得意先の倒産で回収できなくなった。貸倒引当金の残高は45,000である。仕訳を示しなさい。", "a": ["(借)貸倒引当金 45,000 (借)貸倒損失 15,000 (貸)売掛金 60,000"], "e": "前期以前の売掛金の貸倒れは、まず貸倒引当金を取り崩します。足りない15,000は貸倒損失(費用)にします。"}, {"q": "前期に発生した売掛金70,000が、得意先の倒産で回収できなくなった。貸倒引当金の残高は20,000である。仕訳を示しなさい。", "a": ["(借)貸倒引当金 20,000 (借)貸倒損失 50,000 (貸)売掛金 70,000"], "e": "前期以前の売掛金の貸倒れは、まず貸倒引当金を取り崩します。足りない50,000は貸倒損失(費用)にします。"}], "6": [{"q": "当座預金の残高は200,000で、当座借越契約(限度額600,000)がある。買掛金260,000を、小切手を振り出して支払った。その後取引はなく決算日を迎えた。期中と決算時の仕訳を示しなさい。", "a": ["期中:(借)買掛金 260,000 (貸)当座預金 260,000", "決算:(借)当座預金 60,000 (貸)当座借越 60,000"], "e": "期中は当座預金勘定だけで処理し、残高がマイナス(貸方60,000)になっても構いません。決算で、貸方残高を当座借越(負債。借入金とすることもあります)に振り替えます。"}, {"q": "当座預金の残高は80,000で、当座借越契約(限度額400,000)がある。買掛金200,000を、小切手を振り出して支払った。その後取引はなく決算日を迎えた。期中と決算時の仕訳を示しなさい。", "a": ["期中:(借)買掛金 200,000 (貸)当座預金 200,000", "決算:(借)当座預金 120,000 (貸)当座借越 120,000"], "e": "期中は当座預金勘定だけで処理し、残高がマイナス(貸方120,000)になっても構いません。決算で、貸方残高を当座借越(負債。借入金とすることもあります)に振り替えます。"}]}, "t3": {"0": [{"q": "取得原価900,000の備品(耐用年数6年、残存価額ゼロ)について、決算で減価償却を行う。仕訳を示しなさい(間接法)。", "a": ["(借)減価償却費 150,000 (貸)減価償却累計額 150,000"], "e": "900,000÷6年=150,000です。間接法では、備品を直接減らさずに「減価償却累計額」を貸方に書きます。"}, {"q": "取得原価480,000の備品(耐用年数4年、残存価額ゼロ)について、決算で減価償却を行う。仕訳を示しなさい(間接法)。", "a": ["(借)減価償却費 120,000 (貸)減価償却累計額 120,000"], "e": "480,000÷4年=120,000です。間接法では、備品を直接減らさずに「減価償却累計額」を貸方に書きます。"}], "1": [{"q": "決算で、売掛金600,000と受取手形400,000に3%の貸倒引当金を設定する。貸倒引当金の残高は8,000である(差額補充法)。仕訳を示しなさい。", "a": ["(借)貸倒引当金繰入 22,000 (貸)貸倒引当金 22,000"], "e": "設定額=(600,000+400,000)×3%=30,000です。すでに8,000あるので、差額の22,000を繰り入れます。"}, {"q": "決算で、売掛金450,000と受取手形250,000に4%の貸倒引当金を設定する。貸倒引当金の残高は12,000である(差額補充法)。仕訳を示しなさい。", "a": ["(借)貸倒引当金繰入 16,000 (貸)貸倒引当金 16,000"], "e": "設定額=(450,000+250,000)×4%=28,000です。すでに12,000あるので、差額の16,000を繰り入れます。"}], "2": [{"q": "期首商品は80,000、当期の仕入は600,000、期末商品は90,000である。売上原価を「仕入」勘定で計算する仕訳を示し、売上原価を求めなさい。", "a": ["(借)仕入 80,000 (貸)繰越商品 80,000", "(借)繰越商品 90,000 (貸)仕入 90,000", "売上原価 590,000"], "e": "期首商品を仕入に足し、期末商品を仕入から引きます。売上原価=80,000+600,000−90,000=590,000です。"}, {"q": "期首商品は30,000、当期の仕入は500,000、期末商品は45,000である。売上原価を「仕入」勘定で計算する仕訳を示し、売上原価を求めなさい。", "a": ["(借)仕入 30,000 (貸)繰越商品 30,000", "(借)繰越商品 45,000 (貸)仕入 45,000", "売上原価 485,000"], "e": "期首商品を仕入に足し、期末商品を仕入から引きます。売上原価=30,000+500,000−45,000=485,000です。"}], "3": [{"q": "決算日は3月31日である。\n(1)11月1日に、保険料12か月分96,000を支払っていた。前払分を計上する。\n(2)給料の未払いが60,000ある。\n(3)受取家賃のうち、36,000は次期分を受け取っていた。\n(4)受取利息の未収分が8,000ある。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)前払保険料 56,000 (貸)支払保険料 56,000", "(2)(借)給料 60,000 (貸)未払給料 60,000", "(3)(借)受取家賃 36,000 (貸)前受家賃 36,000", "(4)(借)未収利息 8,000 (貸)受取利息 8,000"], "e": "(1)保険料は11/1〜10/31の12か月分で、決算日(3/31)までに5か月経過、残り7か月分=96,000×7÷12=56,000が前払いです。(2)と(4)は、当期の費用・収益なのにまだ記録していない分を足します。(3)は、次期の収益を引きます。"}, {"q": "決算日は3月31日である。\n(1)11月1日に、保険料12か月分72,000を支払っていた。前払分を計上する。\n(2)給料の未払いが25,000ある。\n(3)受取家賃のうち、48,000は次期分を受け取っていた。\n(4)受取利息の未収分が12,000ある。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)前払保険料 42,000 (貸)支払保険料 42,000", "(2)(借)給料 25,000 (貸)未払給料 25,000", "(3)(借)受取家賃 48,000 (貸)前受家賃 48,000", "(4)(借)未収利息 12,000 (貸)受取利息 12,000"], "e": "(1)保険料は11/1〜10/31の12か月分で、決算日(3/31)までに5か月経過、残り7か月分=72,000×7÷12=42,000が前払いです。(2)と(4)は、当期の費用・収益なのにまだ記録していない分を足します。(3)は、次期の収益を引きます。"}], "4": [{"q": "決算で、現金過不足が(1)借方残高4,000、(2)貸方残高5,000のまま、原因が分からなかった。それぞれの仕訳を示しなさい。", "a": ["(1)(借)雑損 4,000 (貸)現金過不足 4,000", "(2)(借)現金過不足 5,000 (貸)雑益 5,000"], "e": "借方残高(不足)は「雑損」(費用)、貸方残高(過剰)は「雑益」(収益)にして、現金過不足を消します。"}, {"q": "決算で、現金過不足が(1)借方残高1,000、(2)貸方残高6,000のまま、原因が分からなかった。それぞれの仕訳を示しなさい。", "a": ["(1)(借)雑損 1,000 (貸)現金過不足 1,000", "(2)(借)現金過不足 6,000 (貸)雑益 6,000"], "e": "借方残高(不足)は「雑損」(費用)、貸方残高(過剰)は「雑益」(収益)にして、現金過不足を消します。"}], "5": [{"q": "次の資料から、売上総利益、営業利益、当期純利益を求めなさい(法人税等は考えない)。\n・売上高 1,200,000 / 売上原価 720,000\n・給料 200,000 / 減価償却費 60,000 / 支払家賃 80,000\n・受取利息 12,000 / 支払利息 5,000", "a": ["売上総利益 480,000", "営業利益 140,000", "当期純利益 147,000"], "e": "売上総利益=1,200,000−720,000=480,000。営業利益=480,000−(200,000+60,000+80,000)=140,000。当期純利益=140,000+受取利息12,000−支払利息5,000=147,000。"}, {"q": "次の資料から、売上総利益、営業利益、当期純利益を求めなさい(法人税等は考えない)。\n・売上高 750,000 / 売上原価 450,000\n・給料 120,000 / 減価償却費 40,000 / 支払家賃 50,000\n・受取利息 15,000 / 支払利息 6,000", "a": ["売上総利益 300,000", "営業利益 90,000", "当期純利益 99,000"], "e": "売上総利益=750,000−450,000=300,000。営業利益=300,000−(120,000+40,000+50,000)=90,000。当期純利益=90,000+受取利息15,000−支払利息6,000=99,000。"}]}, "k1": {"0": [{"q": "月初材料200個(原価合計24,000)、当月仕入300個(購入原価合計42,000)、当月消費320個です。総平均法で消費額と月末材料の金額を求めなさい。", "a": ["消費額 42,240", "月末材料 23,760"], "e": "総平均単価=(24,000+42,000)÷(200+300)=132。消費320個×132=42,240、月末180個×132=23,760。"}, {"q": "月初材料150個(原価合計21,000)、当月仕入450個(購入原価合計65,400)、当月消費400個です。総平均法で消費額と月末材料の金額を求めなさい。", "a": ["消費額 57,600", "月末材料 28,800"], "e": "総平均単価=(21,000+65,400)÷(150+450)=144。消費400個×144=57,600、月末200個×144=28,800。"}], "1": [{"q": "当月の賃金支払額は900,000、前月未払賃金は150,000、当月未払賃金は130,000です。賃金の当月実際消費額を求めなさい。", "a": ["880,000"], "e": "当月支払900,000−前月未払150,000+当月未払130,000=880,000。支払額には前月分が含まれ、当月未払は当月の消費なので加えます。"}, {"q": "当月の賃金支払額は750,000、前月未払賃金は80,000、当月未払賃金は110,000です。賃金の当月実際消費額を求めなさい。", "a": ["780,000"], "e": "当月支払750,000−前月未払80,000+当月未払110,000=780,000。支払額には前月分が含まれ、当月未払は当月の消費なので加えます。"}], "2": [{"q": "直接工の予定賃率は、1時間あたり1,800です。当月の作業時間は直接作業410時間、間接作業70時間です。問2の実際消費額(880,000)をこの直接工の分として、(1)予定賃率による消費の仕訳と、(2)賃率差異の計上の仕訳を示しなさい。", "a": ["(1)(借)仕掛品 738,000 (借)製造間接費 126,000 (貸)賃金 864,000", "(2)(借)賃率差異 16,000 (貸)賃金 16,000"], "e": "直接作業410時間×1,800=738,000、間接作業70時間×1,800=126,000。予定消費864,000と実際880,000の差16,000は実際が多いので不利差異(借方)です。"}, {"q": "直接工の予定賃率は、1時間あたり1,500です。当月の作業時間は直接作業480時間、間接作業30時間です。問2の実際消費額(780,000)をこの直接工の分として、(1)予定賃率による消費の仕訳と、(2)賃率差異の計上の仕訳を示しなさい。", "a": ["(1)(借)仕掛品 720,000 (借)製造間接費 45,000 (貸)賃金 765,000", "(2)(借)賃率差異 15,000 (貸)賃金 15,000"], "e": "直接作業480時間×1,500=720,000、間接作業30時間×1,500=45,000。予定消費765,000と実際780,000の差15,000は実際が多いので不利差異(借方)です。"}], "3": [{"q": "年間予算の製造間接費は27,000,000、年間予定直接作業時間は30,000時間です。当月の実際直接作業時間は2,500時間、製造間接費の実際発生額は2,310,000です。予定配賦率、予定配賦額、配賦差異(有利・不利を明記)を求めなさい。", "a": ["予定配賦率 900円/時間", "予定配賦額 2,250,000", "配賦差異 60,000(不利)"], "e": "27,000,000÷30,000=900。2,500×900=2,250,000。実際2,310,000より60,000少ない(配賦不足)ので不利差異です。"}, {"q": "年間予算の製造間接費は18,000,000、年間予定直接作業時間は36,000時間です。当月の実際直接作業時間は3,000時間、製造間接費の実際発生額は1,530,000です。予定配賦率、予定配賦額、配賦差異(有利・不利を明記)を求めなさい。", "a": ["予定配賦率 500円/時間", "予定配賦額 1,500,000", "配賦差異 30,000(不利)"], "e": "18,000,000÷36,000=500。3,000×500=1,500,000。実際1,530,000より30,000少ない(配賦不足)ので不利差異です。"}], "4": [{"q": "月間の固定費予算1,500,000、変動費率は1時間あたり250、基準操業度は5,000時間です。当月の実際操業度は4,600時間、実際発生額は2,700,000です。予算差異と操業度差異を求めなさい。", "a": ["予算差異 50,000(不利)", "操業度差異 120,000(不利)"], "e": "予算許容額=250×4,600+1,500,000=2,650,000。予算差異=2,650,000−2,700,000=−50,000。固定費率=1,500,000÷5,000=300、操業度差異=(4,600−5,000)×300=−120,000。予定配賦率=変動費率250+固定費率300=550なので、配賦額=4,600×550=2,530,000。これと実際2,700,000の差170,000と一致します。"}, {"q": "月間の固定費予算900,000、変動費率は1時間あたり150、基準操業度は3,000時間です。当月の実際操業度は2,700時間、実際発生額は1,380,000です。予算差異と操業度差異を求めなさい。", "a": ["予算差異 75,000(不利)", "操業度差異 90,000(不利)"], "e": "予算許容額=150×2,700+900,000=1,305,000。予算差異=1,305,000−1,380,000=−75,000。固定費率=900,000÷3,000=300、操業度差異=(2,700−3,000)×300=−90,000。予定配賦率=変動費率150+固定費率300=450なので、配賦額=2,700×450=1,215,000。これと実際1,380,000の差165,000と一致します。"}], "5": [{"q": "製造部門は第1と第2、補助部門は動力と修繕です。部門費は第1製造500,000、第2製造350,000、動力120,000、修繕80,000です。動力の供給量は第1が700kWh、第2が300kWh、修繕の回数は第1が3回、第2が1回です。直接配賦法で補助部門費を配賦した後の、第1・第2製造部門費を求めなさい。", "a": ["第1製造部門 644,000", "第2製造部門 406,000"], "e": "動力120,000を700:300で、第1 84,000・第2 36,000。修繕80,000を3:1で、第1 60,000・第2 20,000。第1=500,000+84,000+60,000、第2=350,000+36,000+20,000。合計1,050,000が元の合計と一致します。"}, {"q": "製造部門は第1と第2、補助部門は動力と修繕です。部門費は第1製造450,000、第2製造280,000、動力90,000、修繕70,000です。動力の供給量は第1が400kWh、第2が200kWh、修繕の回数は第1が4回、第2が3回です。直接配賦法で補助部門費を配賦した後の、第1・第2製造部門費を求めなさい。", "a": ["第1製造部門 550,000", "第2製造部門 340,000"], "e": "動力90,000を400:200で、第1 60,000・第2 30,000。修繕70,000を4:3で、第1 40,000・第2 30,000。第1=450,000+60,000+40,000、第2=280,000+30,000+30,000。合計890,000が元の合計と一致します。"}], "6": [{"q": "部門費は第1製造500,000、第2製造400,000、動力150,000、修繕80,000です。動力部門の供給割合は修繕20%・第1製造40%・第2製造40%、修繕部門の供給割合は動力10%・第1製造60%・第2製造30%です。相互配賦法(第1次配賦で相互に配賦し、第2次配賦で製造部門へ直接配賦する簡便法)で、第1・第2製造部門費を求めなさい。", "a": ["第1製造部門 632,000", "第2製造部門 498,000"], "e": "第1次:動力→修繕30,000・第1 60,000・第2 60,000、修繕→動力8,000・第1 48,000・第2 24,000。第2次:修繕30,000を2:1で第1 20,000・第2 10,000、動力8,000を第1・第2に4,000ずつ。第1=500,000+60,000+48,000+20,000+4,000、第2=400,000+60,000+24,000+10,000+4,000。合計1,130,000で検算できます。"}, {"q": "部門費は第1製造360,000、第2製造240,000、動力200,000、修繕120,000です。動力部門の供給割合は修繕10%・第1製造60%・第2製造30%、修繕部門の供給割合は動力20%・第1製造40%・第2製造40%です。相互配賦法(第1次配賦で相互に配賦し、第2次配賦で製造部門へ直接配賦する簡便法)で、第1・第2製造部門費を求めなさい。", "a": ["第1製造部門 554,000", "第2製造部門 366,000"], "e": "第1次:動力→修繕20,000・第1 120,000・第2 60,000、修繕→動力24,000・第1 48,000・第2 48,000。第2次:修繕20,000を第1・第2に10,000ずつ、動力24,000を2:1で第1 16,000・第2 8,000。第1=360,000+120,000+48,000+10,000+16,000、第2=240,000+60,000+48,000+10,000+8,000。合計920,000で検算できます。"}]}, "k2": {"0": [{"q": "製造指図書#102の直接材料費は360,000、直接労務費は240,000、直接作業時間は120時間です。製造間接費は直接作業時間1時間あたり1,250円で配賦します。#102が完成し、売価1,000,000で掛け売りしました。製品への振替、売上、売上原価の仕訳を示しなさい。", "a": ["(借)製品 750,000 (貸)仕掛品 750,000", "(借)売掛金 1,000,000 (貸)売上 1,000,000", "(借)売上原価 750,000 (貸)製品 750,000"], "e": "製造間接費の配賦額=120時間×1,250=150,000。製造原価=360,000+240,000+150,000=750,000です。製品の売上と売上原価は、必ずセットで仕訳します。"}, {"q": "製造指図書#201の直接材料費は420,000、直接労務費は280,000、直接作業時間は80時間です。製造間接費は直接作業時間1時間あたり1,800円で配賦します。#201が完成し、売価1,100,000で掛け売りしました。製品への振替、売上、売上原価の仕訳を示しなさい。", "a": ["(借)製品 844,000 (貸)仕掛品 844,000", "(借)売掛金 1,100,000 (貸)売上 1,100,000", "(借)売上原価 844,000 (貸)製品 844,000"], "e": "製造間接費の配賦額=80時間×1,800=144,000。製造原価=420,000+280,000+144,000=844,000です。製品の売上と売上原価は、必ずセットで仕訳します。"}], "1": [{"q": "製造指図書#401が全部仕損となり、新たに代品製造の指図書#401-2を発行しました。#401の製造原価は640,000、仕損品の評価額は80,000です。仕損は正常なもので、仕損費は#401-2に賦課します。この仕訳を示しなさい。", "a": ["(借)仕損品 80,000 (借)仕掛品(#401-2) 560,000 (貸)仕掛品(#401) 640,000"], "e": "仕損費=640,000−80,000=560,000です。全部仕損では、旧指図書の製造原価から評価額を引いた額を、代品の指図書へ賦課します。いったん仕損費勘定を通して「(借)仕損品 80,000 (借)仕損費 560,000 (貸)仕掛品 640,000」「(借)仕掛品 560,000 (貸)仕損費 560,000」と書く方法もあり、どちらでも正解です。"}, {"q": "製造指図書#502が全部仕損となり、新たに代品製造の指図書#502-2を発行しました。#502の製造原価は380,000、仕損品の評価額は50,000です。仕損は正常なもので、仕損費は#502-2に賦課します。この仕訳を示しなさい。", "a": ["(借)仕損品 50,000 (借)仕掛品(#502-2) 330,000 (貸)仕掛品(#502) 380,000"], "e": "仕損費=380,000−50,000=330,000です。全部仕損では、旧指図書の製造原価から評価額を引いた額を、代品の指図書へ賦課します。いったん仕損費勘定を通して「(借)仕損品 50,000 (借)仕損費 330,000 (貸)仕掛品 380,000」「(借)仕掛品 330,000 (貸)仕損費 330,000」と書く方法もあり、どちらでも正解です。"}], "2": [{"q": "材料は始点投入です。月初仕掛品は100個(加工進捗40%)で、材料費25,000、加工費18,000です。当月は900個を投入し、材料費225,000、加工費252,000が発生しました。完成品は800個、月末仕掛品は200個(加工進捗50%)です。平均法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 440,000", "月末仕掛品原価 80,000"], "e": "材料費は始点投入なので数量で按分します。(25,000+225,000)÷(800+200)=250、完成800×250=200,000、月末200×250=50,000。加工費は完成品換算量が800+200×50%=900なので、(18,000+252,000)÷900=300、完成240,000、月末100×300=30,000です。完成品=200,000+240,000=440,000、月末=50,000+30,000=80,000。"}, {"q": "材料は始点投入です。月初仕掛品は300個(加工進捗60%)で、材料費36,000、加工費45,000です。当月は700個を投入し、材料費124,000、加工費147,000が発生しました。完成品は750個、月末仕掛品は250個(加工進捗20%)です。平均法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 300,000", "月末仕掛品原価 52,000"], "e": "材料費は始点投入なので数量で按分します。(36,000+124,000)÷(750+250)=160、完成750×160=120,000、月末250×160=40,000。加工費は完成品換算量が750+250×20%=800なので、(45,000+147,000)÷800=240、完成180,000、月末50×240=12,000です。完成品=120,000+180,000=300,000、月末=40,000+12,000=52,000。"}], "3": [{"q": "材料は始点投入です。月初仕掛品は100個(加工進捗40%)で、材料費18,000、加工費10,000です。当月は900個を投入し、材料費225,000、加工費258,000が発生しました。完成品は800個、月末仕掛品は200個(加工進捗50%)です。先入先出法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 431,000", "月末仕掛品原価 80,000"], "e": "先入先出法は当月投入分だけで単価を出します。材料は225,000÷900=250、月末200×250=50,000です。加工費の当月換算量は800+100−100×40%=860、258,000÷860=300、月末100×300=30,000です。月末=80,000、完成品=(18,000+10,000+225,000+258,000)−80,000=431,000。"}, {"q": "材料は始点投入です。月初仕掛品は300個(加工進捗20%)で、材料費45,000、加工費12,000です。当月は700個を投入し、材料費126,000、加工費158,000が発生しました。完成品は750個、月末仕掛品は250個(加工進捗40%)です。先入先出法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 276,000", "月末仕掛品原価 65,000"], "e": "先入先出法は当月投入分だけで単価を出します。材料は126,000÷700=180、月末250×180=45,000です。加工費の当月換算量は750+100−300×20%=790、158,000÷790=200、月末100×200=20,000です。月末=65,000、完成品=(45,000+12,000+126,000+158,000)−65,000=276,000。"}], "4": [{"q": "材料は始点投入で、月初仕掛品は200個(加工進捗50%)、材料費36,000、加工費24,000です。当月は800個を投入し、材料費164,000、加工費181,000が発生しました。完成品は650個、正常仕損は50個、月末仕掛品は300個(加工進捗40%)です。仕損は工程の終点で発生し、仕損品の評価額はありません。平均法・度外視法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 315,000", "月末仕掛品原価 90,000"], "e": "仕損が終点で発生するので、月末仕掛品(加工進捗40%)は仕損の発生点を通過せず、仕損費は完成品だけが負担します。材料は(36,000+164,000)÷(650+50+300)=200、月末300×200=60,000です。加工費の換算量は650+50+300×40%=820、(24,000+181,000)÷820=250、月末120×250=30,000です。月末=90,000、完成品=(60,000+345,000)−90,000=315,000(仕損費を含む)。"}, {"q": "材料は始点投入で、月初仕掛品は150個(加工進捗60%)、材料費24,000、加工費27,000です。当月は850個を投入し、材料費136,000、加工費163,000が発生しました。完成品は720個、正常仕損は30個、月末仕掛品は250個(加工進捗80%)です。仕損は工程の終点で発生し、仕損品の評価額はありません。平均法・度外視法で、完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 270,000", "月末仕掛品原価 80,000"], "e": "仕損が終点で発生するので、月末仕掛品(加工進捗80%)は仕損の発生点を通過せず、仕損費は完成品だけが負担します。材料は(24,000+136,000)÷(720+30+250)=160、月末250×160=40,000です。加工費の換算量は720+30+250×80%=950、(27,000+163,000)÷950=200、月末200×200=40,000です。月末=80,000、完成品=(160,000+190,000)−80,000=270,000(仕損費を含む)。"}], "5": [{"q": "第1工程の完成品600個(原価540,000)を、すべて第2工程に始点投入しました。第2工程の月初仕掛品は200個(加工進捗50%)で、前工程費140,000、加工費30,000です。第2工程の当月加工費は110,000です。完成品は600個、月末仕掛品は200個(加工進捗50%)です。平均法で、第2工程の完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 630,000", "月末仕掛品原価 190,000"], "e": "前工程費は始点投入なので数量で按分します。(140,000+540,000)÷(600+200)=850、完成600×850=510,000、月末200×850=170,000。加工費は換算量600+200×50%=700で、(30,000+110,000)÷700=200、完成120,000、月末100×200=20,000。完成品=510,000+120,000=630,000、月末=170,000+20,000=190,000。"}, {"q": "第1工程の完成品400個(原価340,000)を、すべて第2工程に始点投入しました。第2工程の月初仕掛品は100個(加工進捗60%)で、前工程費110,000、加工費18,000です。第2工程の当月加工費は58,000です。完成品は350個、月末仕掛品は150個(加工進捗20%)です。平均法で、第2工程の完成品総合原価と月末仕掛品原価を求めなさい。", "a": ["完成品総合原価 385,000", "月末仕掛品原価 141,000"], "e": "前工程費は始点投入なので数量で按分します。(110,000+340,000)÷(350+150)=900、完成350×900=315,000、月末150×900=135,000。加工費は換算量350+150×20%=380で、(18,000+58,000)÷380=200、完成70,000、月末30×200=6,000。完成品=315,000+70,000=385,000、月末=135,000+6,000=141,000。"}], "6": [{"q": "組間接費(加工費)の当月発生額は720,000で、直接作業時間を基準にA組・B組へ配賦します。直接作業時間はA組2,000時間、B組1,000時間です。A組の組直接費(材料費)は600,000です。A組・B組への配賦額と、A組の当月製造費用を求めなさい。", "a": ["A組への配賦額 480,000", "B組への配賦額 240,000", "A組の当月製造費用 1,080,000"], "e": "配賦率=720,000÷(2,000+1,000)=240円/時間。A組=2,000×240=480,000、B組=1,000×240=240,000。A組の当月製造費用=600,000+480,000=1,080,000です。"}, {"q": "組間接費(加工費)の当月発生額は900,000で、直接作業時間を基準にA組・B組へ配賦します。直接作業時間はA組1,200時間、B組1,800時間です。A組の組直接費(材料費)は450,000です。A組・B組への配賦額と、A組の当月製造費用を求めなさい。", "a": ["A組への配賦額 360,000", "B組への配賦額 540,000", "A組の当月製造費用 810,000"], "e": "配賦率=900,000÷(1,200+1,800)=300円/時間。A組=1,200×300=360,000、B組=1,800×300=540,000。A組の当月製造費用=450,000+360,000=810,000です。"}], "7": [{"q": "完成品総合原価は1,650,000です。等価係数は1級品が1.0、2級品が0.5で、完成数量は1級品800個、2級品600個です。各等級の完成品原価と1個あたりの原価を求めなさい。", "a": ["1級品 1,200,000(1個 1,500)", "2級品 450,000(1個 750)"], "e": "積数は1級品800×1.0=800、2級品600×0.5=300で、比は8:3です。1,650,000を按分して、1級品1,200,000、2級品450,000。1個あたりは1,200,000÷800=1,500、450,000÷600=750です。"}, {"q": "完成品総合原価は1,260,000です。等価係数は1級品が1.0、2級品が0.8で、完成数量は1級品500個、2級品500個です。各等級の完成品原価と1個あたりの原価を求めなさい。", "a": ["1級品 700,000(1個 1,400)", "2級品 560,000(1個 1,120)"], "e": "積数は1級品500×1.0=500、2級品500×0.8=400で、比は5:4です。1,260,000を按分して、1級品700,000、2級品560,000。1個あたりは700,000÷500=1,400、560,000÷500=1,120です。"}]}, "k3": {"0": [{"q": "製品1個あたりの標準消費量は4kg、標準単価は1kgあたり250円です。当月の完成品は500個(月初・月末仕掛品なし)で、実際消費量は2,060kg、実際単価は1kgあたり245円でした。材料費差異を、価格差異と数量差異に分けて求めなさい。", "a": ["価格差異 10,300(有利)", "数量差異 15,000(不利)", "材料費差異 4,700(不利)"], "e": "標準消費量=500個×4kg=2,000kg。価格差異=(250−245)×2,060kg=10,300。数量差異=(2,000−2,060)×250=−15,000。標準原価500,000と実際原価504,700の差−4,700と一致します。"}, {"q": "製品1個あたりの標準消費量は6kg、標準単価は1kgあたり150円です。当月の完成品は300個(月初・月末仕掛品なし)で、実際消費量は1,780kg、実際単価は1kgあたり155円でした。材料費差異を、価格差異と数量差異に分けて求めなさい。", "a": ["価格差異 8,900(不利)", "数量差異 3,000(有利)", "材料費差異 5,900(不利)"], "e": "標準消費量=300個×6kg=1,800kg。価格差異=(150−155)×1,780kg=−8,900。数量差異=(1,800−1,780)×150=3,000。標準原価270,000と実際原価275,900の差−5,900と一致します。"}], "1": [{"q": "製品1個あたりの標準直接作業時間は3時間、標準賃率は1時間あたり1,200円です。当月の完成品は500個で、実際直接作業時間は1,540時間、実際賃率は1時間あたり1,250円でした。賃率差異と作業時間差異を求めなさい。", "a": ["賃率差異 77,000(不利)", "作業時間差異 48,000(不利)"], "e": "標準時間=500個×3時間=1,500時間。賃率差異=(1,200−1,250)×1,540時間=−77,000。作業時間差異=(1,500−1,540)×1,200=−48,000。標準1,800,000と実際1,925,000の差−125,000と一致します。"}, {"q": "製品1個あたりの標準直接作業時間は2時間、標準賃率は1時間あたり1,500円です。当月の完成品は800個で、実際直接作業時間は1,570時間、実際賃率は1時間あたり1,520円でした。賃率差異と作業時間差異を求めなさい。", "a": ["賃率差異 31,400(不利)", "作業時間差異 45,000(有利)"], "e": "標準時間=800個×2時間=1,600時間。賃率差異=(1,500−1,520)×1,570時間=−31,400。作業時間差異=(1,600−1,570)×1,500=45,000。標準2,400,000と実際2,386,400の差13,600と一致します。"}], "2": [{"q": "基準操業度は月1,600直接作業時間、固定費予算は960,000、変動費率は1時間あたり400円です。標準直接作業時間は問2の1,500時間、実際直接作業時間は1,540時間、実際発生額は1,590,000でした。予算差異、能率差異、操業度差異を求めなさい(3分法)。", "a": ["予算差異 14,000(不利)", "能率差異 40,000(不利)", "操業度差異 36,000(不利)"], "e": "標準配賦率=960,000÷1,600+400=1,000。予算許容額=400×1,540+960,000=1,576,000なので、予算差異=1,576,000−1,590,000=−14,000。能率差異=(1,500−1,540)×1,000=−40,000。操業度差異=(1,540−1,600)×600=−36,000(固定費率は960,000÷1,600=600)。合計−90,000は、標準配賦額1,500,000と実際1,590,000の差と一致します。"}, {"q": "基準操業度は月1,500直接作業時間、固定費予算は750,000、変動費率は1時間あたり600円です。標準直接作業時間は問2の1,600時間、実際直接作業時間は1,570時間、実際発生額は1,700,000でした。予算差異、能率差異、操業度差異を求めなさい(3分法)。", "a": ["予算差異 8,000(不利)", "能率差異 33,000(有利)", "操業度差異 35,000(有利)"], "e": "標準配賦率=750,000÷1,500+600=1,100。予算許容額=600×1,570+750,000=1,692,000なので、予算差異=1,692,000−1,700,000=−8,000。能率差異=(1,600−1,570)×1,100=33,000。操業度差異=(1,570−1,500)×500=35,000(固定費率は750,000÷1,500=500)。合計60,000は、標準配賦額1,760,000と実際1,700,000の差と一致します。"}], "3": [{"q": "販売単価は1,200、変動製造費は1個580、変動販売費は1個80、固定製造費は月300,000、固定販売費及び一般管理費は月150,000です。当月の生産量は1,500個、販売量は1,200個で、期首の在庫はありません。直接原価計算の営業利益と全部原価計算の営業利益を求め、差額の理由を説明しなさい。", "a": ["直接原価計算の営業利益 198,000", "全部原価計算の営業利益 258,000", "差額 60,000(理由:期末在庫300個に含まれる固定製造費60,000が、全部原価計算では次期に繰り延べられるため)"], "e": "直接原価計算:売上1,440,000−変動売上原価696,000−変動販売費96,000=貢献利益648,000、固定費450,000を引いて198,000。全部原価計算:製造単価=580+300,000÷1,500=780、売上原価=1,200×780=936,000、売上総利益504,000から販売費及び一般管理費246,000を引いて258,000。差額は、期末在庫300個に含まれる固定製造費(300個×200=60,000)が、全部原価計算では次期に繰り延べられるためです。"}, {"q": "販売単価は900、変動製造費は1個300、変動販売費は1個60、固定製造費は月360,000、固定販売費及び一般管理費は月90,000です。当月の生産量は1,200個、販売量は900個で、期首の在庫はありません。直接原価計算の営業利益と全部原価計算の営業利益を求め、差額の理由を説明しなさい。", "a": ["直接原価計算の営業利益 36,000", "全部原価計算の営業利益 126,000", "差額 90,000(理由:期末在庫300個に含まれる固定製造費90,000が、全部原価計算では次期に繰り延べられるため)"], "e": "直接原価計算:売上810,000−変動売上原価270,000−変動販売費54,000=貢献利益486,000、固定費450,000を引いて36,000。全部原価計算:製造単価=300+360,000÷1,200=600、売上原価=900×600=540,000、売上総利益270,000から販売費及び一般管理費144,000を引いて126,000。差額は、期末在庫300個に含まれる固定製造費(300個×300=90,000)が、全部原価計算では次期に繰り延べられるためです。"}], "4": [{"q": "問4の資料(販売単価は1,200、変動費は1個あたり660、固定費は合計450,000)で、貢献利益率、損益分岐点売上高、営業利益90,000を得るための売上高、売上高2,000,000のときの安全余裕率を求めなさい。", "a": ["貢献利益率 45%", "損益分岐点売上高 1,000,000", "目標売上高 1,200,000", "安全余裕率 50%"], "e": "貢献利益率=(1,200−660)÷1,200=45%。損益分岐点売上高=450,000÷0.45=1,000,000。目標売上高=(450,000+90,000)÷0.45=1,200,000。安全余裕率=(2,000,000−1,000,000)÷2,000,000=50%です。"}, {"q": "問4の資料(販売単価は900、変動費は1個あたり360、固定費は合計450,000)で、貢献利益率、損益分岐点売上高、営業利益150,000を得るための売上高、売上高1,250,000のときの安全余裕率を求めなさい。", "a": ["貢献利益率 60%", "損益分岐点売上高 750,000", "目標売上高 1,000,000", "安全余裕率 40%"], "e": "貢献利益率=(900−360)÷900=60%。損益分岐点売上高=450,000÷0.6=750,000。目標売上高=(450,000+150,000)÷0.6=1,000,000。安全余裕率=(1,250,000−750,000)÷1,250,000=40%です。"}], "5": [{"q": "工場の会計が独立している場合の、本社と工場の仕訳を示しなさい。\n(1)本社が材料500,000を掛けで購入し、工場に納入した。\n(2)本社が工場の賃金250,000を現金で支払った。\n(3)工場が完成品800,000を本社に引き渡した(製品は本社が管理する)。", "a": ["(1)本社:(借)工場 500,000 (貸)買掛金 500,000", "(1)工場:(借)材料 500,000 (貸)本社 500,000", "(2)本社:(借)工場 250,000 (貸)現金 250,000", "(2)工場:(借)賃金 250,000 (貸)本社 250,000", "(3)工場:(借)本社 800,000 (貸)仕掛品 800,000", "(3)本社:(借)製品 800,000 (貸)工場 800,000"], "e": "本社には「工場」勘定、工場には「本社」勘定を置き、貸借を互いに対応させます。内部の取引は、本社の「工場」と工場の「本社」が必ず同額で逆の関係になり、本社と工場を合算した財務諸表では相殺されます。(3)は製品勘定が本社にあるので、工場は仕掛品から直接本社へ引き渡したと記帳します。"}, {"q": "工場の会計が独立している場合の、本社と工場の仕訳を示しなさい。\n(1)本社が材料360,000を掛けで購入し、工場に納入した。\n(2)本社が工場の賃金180,000を現金で支払った。\n(3)工場が完成品540,000を本社に引き渡した(製品は本社が管理する)。", "a": ["(1)本社:(借)工場 360,000 (貸)買掛金 360,000", "(1)工場:(借)材料 360,000 (貸)本社 360,000", "(2)本社:(借)工場 180,000 (貸)現金 180,000", "(2)工場:(借)賃金 180,000 (貸)本社 180,000", "(3)工場:(借)本社 540,000 (貸)仕掛品 540,000", "(3)本社:(借)製品 540,000 (貸)工場 540,000"], "e": "本社には「工場」勘定、工場には「本社」勘定を置き、貸借を互いに対応させます。内部の取引は、本社の「工場」と工場の「本社」が必ず同額で逆の関係になり、本社と工場を合算した財務諸表では相殺されます。(3)は製品勘定が本社にあるので、工場は仕掛品から直接本社へ引き渡したと記帳します。"}]}, "s1": {"0": [{"q": "商品と1年間の保守サービスを合わせて135,000で販売し、代金は現金で受け取りました。商品の独立販売価格は120,000、保守サービスの独立販売価格は30,000です。(1)販売時の仕訳と、(2)半年が経過した決算時の仕訳を示しなさい。", "a": ["(1)(借)現金 135,000 (貸)売上 108,000 (貸)契約負債 27,000", "(2)(借)契約負債 13,500 (貸)役務収益 13,500"], "e": "独立販売価格の比で按分します。商品=135,000×120÷150=108,000、保守=135,000×30÷150=27,000。保守サービスは1年かけて提供するので、半年分の13,500を決算で収益にします。"}, {"q": "商品と2年間の保守サービスを合わせて190,000で販売し、代金は現金で受け取りました。商品の独立販売価格は160,000、保守サービスの独立販売価格は40,000です。(1)販売時の仕訳と、(2)1年が経過した決算時の仕訳を示しなさい。", "a": ["(1)(借)現金 190,000 (貸)売上 152,000 (貸)契約負債 38,000", "(2)(借)契約負債 19,000 (貸)役務収益 19,000"], "e": "独立販売価格の比で按分します。商品=190,000×160÷200=152,000、保守=190,000×40÷200=38,000。保守サービスは2年かけて提供するので、1年分の19,000を決算で収益にします。"}], "1": [{"q": "商品800,000を掛けで販売しました。一定数量を超えると4%を返金する契約で、返金が見込まれます。販売時の仕訳を示しなさい。", "a": ["(借)売掛金 800,000 (貸)売上 768,000 (貸)返金負債 32,000"], "e": "返金が見込まれる部分(800,000×4%=32,000)は売上にせず、返金負債にします。"}, {"q": "商品600,000を掛けで販売しました。一定数量を超えると10%を返金する契約で、返金が見込まれます。販売時の仕訳を示しなさい。", "a": ["(借)売掛金 600,000 (貸)売上 540,000 (貸)返金負債 60,000"], "e": "返金が見込まれる部分(600,000×10%=60,000)は売上にせず、返金負債にします。"}], "2": [{"q": "受取手形800,000を銀行で割り引き、割引料16,000を差し引かれた手取額が当座預金に入金されました。その後、この手形が不渡りとなり、割引先から手数料4,000を含む804,000の償還請求を受け、当座預金から支払いました。それぞれの仕訳を示しなさい。", "a": ["割引時:(借)当座預金 784,000 (借)手形売却損 16,000 (貸)受取手形 800,000", "不渡り時:(借)不渡手形 804,000 (貸)当座預金 804,000"], "e": "手取額=800,000−16,000=784,000。不渡りでは、手形の額面に償還請求の費用4,000を加えた804,000を、手形の振出人に請求する債権として不渡手形勘定に計上します。"}, {"q": "受取手形450,000を銀行で割り引き、割引料9,000を差し引かれた手取額が当座預金に入金されました。その後、この手形が不渡りとなり、割引先から手数料2,000を含む452,000の償還請求を受け、当座預金から支払いました。それぞれの仕訳を示しなさい。", "a": ["割引時:(借)当座預金 441,000 (借)手形売却損 9,000 (貸)受取手形 450,000", "不渡り時:(借)不渡手形 452,000 (貸)当座預金 452,000"], "e": "手取額=450,000−9,000=441,000。不渡りでは、手形の額面に償還請求の費用2,000を加えた452,000を、手形の振出人に請求する債権として不渡手形勘定に計上します。"}], "3": [{"q": "国庫補助金1,500,000を現金で受け取りました。その後、機械装置5,000,000を現金で購入し、補助金に相当する額の圧縮記帳を行いました。決算で、定額法(耐用年数7年、残存価額ゼロ、期首に取得、間接法)で減価償却しました。補助金の受取時、購入時、圧縮記帳、決算の仕訳を示しなさい。", "a": ["受取時:(借)現金 1,500,000 (貸)国庫補助金受贈益 1,500,000", "購入時:(借)機械装置 5,000,000 (貸)現金 5,000,000", "圧縮記帳:(借)固定資産圧縮損 1,500,000 (貸)機械装置 1,500,000", "決算:(借)減価償却費 500,000 (貸)機械装置減価償却累計額 500,000"], "e": "圧縮後の取得原価は3,500,000で、償却額=3,500,000÷7=500,000です。圧縮記帳で、補助金の受贈益にかかる課税を先に延ばします。"}, {"q": "国庫補助金800,000を現金で受け取りました。その後、機械装置2,400,000を現金で購入し、補助金に相当する額の圧縮記帳を行いました。決算で、定額法(耐用年数8年、残存価額ゼロ、期首に取得、間接法)で減価償却しました。補助金の受取時、購入時、圧縮記帳、決算の仕訳を示しなさい。", "a": ["受取時:(借)現金 800,000 (貸)国庫補助金受贈益 800,000", "購入時:(借)機械装置 2,400,000 (貸)現金 2,400,000", "圧縮記帳:(借)固定資産圧縮損 800,000 (貸)機械装置 800,000", "決算:(借)減価償却費 200,000 (貸)機械装置減価償却累計額 200,000"], "e": "圧縮後の取得原価は1,600,000で、償却額=1,600,000÷8=200,000です。圧縮記帳で、補助金の受贈益にかかる課税を先に延ばします。"}], "4": [{"q": "取得原価4,800,000の機械装置(定額法、耐用年数8年、残存価額ゼロ)を、当期首から3か月後に2,000,000で売却し、代金は後日受け取ります。前期末までの減価償却累計額は2,400,000です(間接法で記帳)。売却時の仕訳を示しなさい(当期分の減価償却は月割りで計上します)。", "a": ["(借)機械装置減価償却累計額 2,400,000 (借)減価償却費 150,000 (借)未収入金 2,000,000 (借)固定資産売却損 250,000 (貸)機械装置 4,800,000"], "e": "年間償却額=4,800,000÷8=600,000で、当期分は600,000×3÷12=150,000です。売却時の帳簿価額=4,800,000−2,400,000−150,000=2,250,000なので、売却価額2,000,000との差250,000が売却損です。"}, {"q": "取得原価2,400,000の備品(定額法、耐用年数6年、残存価額ゼロ)を、当期首から9か月後に1,200,000で売却し、代金は後日受け取ります。前期末までの減価償却累計額は800,000です(間接法で記帳)。売却時の仕訳を示しなさい(当期分の減価償却は月割りで計上します)。", "a": ["(借)備品減価償却累計額 800,000 (借)減価償却費 300,000 (借)未収入金 1,200,000 (借)固定資産売却損 100,000 (貸)備品 2,400,000"], "e": "年間償却額=2,400,000÷6=400,000で、当期分は400,000×9÷12=300,000です。売却時の帳簿価額=2,400,000−800,000−300,000=1,300,000なので、売却価額1,200,000との差100,000が売却損です。"}], "5": [{"q": "年額100,000を4年間、毎年末に現金で後払いするリース契約を結びました。リース料総額は400,000で、見積現金購入価額は360,000です。\n(1)利子込み法での契約時の仕訳\n(2)利子抜き法での契約時の仕訳\n(3)利子抜き法で第1回の支払い(利息は定額法で配分)と、決算時の減価償却(定額法、耐用年数4年、残存価額ゼロ)の仕訳", "a": ["(1)(借)リース資産 400,000 (貸)リース債務 400,000", "(2)(借)リース資産 360,000 (貸)リース債務 360,000", "(3)支払い:(借)リース債務 90,000 (借)支払利息 10,000 (貸)現金 100,000", "(3)償却:(借)減価償却費 90,000 (貸)リース資産減価償却累計額 90,000"], "e": "利子抜き法では、利息総額=400,000−360,000=40,000を4年で均等に配分し、年10,000です。償却額=360,000÷4=90,000です。"}, {"q": "年額200,000を6年間、毎年末に現金で後払いするリース契約を結びました。リース料総額は1,200,000で、見積現金購入価額は1,080,000です。\n(1)利子込み法での契約時の仕訳\n(2)利子抜き法での契約時の仕訳\n(3)利子抜き法で第1回の支払い(利息は定額法で配分)と、決算時の減価償却(定額法、耐用年数6年、残存価額ゼロ)の仕訳", "a": ["(1)(借)リース資産 1,200,000 (貸)リース債務 1,200,000", "(2)(借)リース資産 1,080,000 (貸)リース債務 1,080,000", "(3)支払い:(借)リース債務 180,000 (借)支払利息 20,000 (貸)現金 200,000", "(3)償却:(借)減価償却費 180,000 (貸)リース資産減価償却累計額 180,000"], "e": "利子抜き法では、利息総額=1,200,000−1,080,000=120,000を6年で均等に配分し、年20,000です。償却額=1,080,000÷6=180,000です。"}], "6": [{"q": "自社利用目的のソフトウェアの制作費3,600,000を当座預金で支払いました(制作中)。その後、完成して利用を開始しました。決算(利用開始から6か月)で、5年間の定額法で償却しました。それぞれの仕訳を示しなさい(直接法)。", "a": ["制作中:(借)ソフトウェア仮勘定 3,600,000 (貸)当座預金 3,600,000", "完成時:(借)ソフトウェア 3,600,000 (貸)ソフトウェア仮勘定 3,600,000", "決算:(借)ソフトウェア償却 360,000 (貸)ソフトウェア 360,000"], "e": "償却額=3,600,000÷5×6÷12=360,000です。制作中は仮勘定、利用開始でソフトウェアに振り替えて償却を始めます。"}, {"q": "自社利用目的のソフトウェアの制作費1,800,000を当座預金で支払いました(制作中)。その後、完成して利用を開始しました。決算(利用開始から9か月)で、3年間の定額法で償却しました。それぞれの仕訳を示しなさい(直接法)。", "a": ["制作中:(借)ソフトウェア仮勘定 1,800,000 (貸)当座預金 1,800,000", "完成時:(借)ソフトウェア 1,800,000 (貸)ソフトウェア仮勘定 1,800,000", "決算:(借)ソフトウェア償却 450,000 (貸)ソフトウェア 450,000"], "e": "償却額=1,800,000÷3×9÷12=450,000です。制作中は仮勘定、利用開始でソフトウェアに振り替えて償却を始めます。"}]}, "s2": {"0": [{"q": "C社株式200株を1株3,000円で購入し、現金で支払いました。\n(1)購入時\n(2)決算時(時価は1株3,150円)\n(3)翌期に80株を1株3,200円で売却し現金を受け取ったとき(切放法)\nの仕訳を示しなさい。", "a": ["(1)(借)売買目的有価証券 600,000 (貸)現金 600,000", "(2)(借)売買目的有価証券 30,000 (貸)有価証券評価益 30,000", "(3)(借)現金 256,000 (貸)売買目的有価証券 252,000 (貸)有価証券売却益 4,000"], "e": "期末の評価額は200株×3,150=630,000で、評価益30,000です。切放法では評価後の帳簿価額(3,150)が次期の原価になるため、売却80株の帳簿価額は80×3,150=252,000、売却額は80×3,200=256,000で、売却益は4,000です。"}, {"q": "D社株式50株を1株8,000円で購入し、現金で支払いました。\n(1)購入時\n(2)決算時(時価は1株8,400円)\n(3)翌期に20株を1株8,500円で売却し現金を受け取ったとき(切放法)\nの仕訳を示しなさい。", "a": ["(1)(借)売買目的有価証券 400,000 (貸)現金 400,000", "(2)(借)売買目的有価証券 20,000 (貸)有価証券評価益 20,000", "(3)(借)現金 170,000 (貸)売買目的有価証券 168,000 (貸)有価証券売却益 2,000"], "e": "期末の評価額は50株×8,400=420,000で、評価益20,000です。切放法では評価後の帳簿価額(8,400)が次期の原価になるため、売却20株の帳簿価額は20×8,400=168,000、売却額は20×8,500=170,000で、売却益は2,000です。"}], "1": [{"q": "額面2,000,000の社債を1,880,000で取得しました(満期まで4年、定額法)。取得から1年後の決算の仕訳を示しなさい。", "a": ["(借)満期保有目的債券 30,000 (貸)有価証券利息 30,000"], "e": "償却額=(2,000,000−1,880,000)÷4年=30,000です。取得価額と額面の差を、満期までに少しずつ増やします。"}, {"q": "額面500,000の社債を470,000で取得しました(満期まで6年、定額法)。取得から1年後の決算の仕訳を示しなさい。", "a": ["(借)満期保有目的債券 5,000 (貸)有価証券利息 5,000"], "e": "償却額=(500,000−470,000)÷6年=5,000です。取得価額と額面の差を、満期までに少しずつ増やします。"}], "2": [{"q": "B社株式を600,000で取得し、決算時の時価は690,000でした(全部純資産直入法)。決算時と、翌期首の洗替えの仕訳を示しなさい。", "a": ["決算時:(借)その他有価証券 90,000 (貸)その他有価証券評価差額金 90,000", "翌期首:(借)その他有価証券評価差額金 90,000 (貸)その他有価証券 90,000"], "e": "評価差額=690,000−600,000=90,000です。評価差額は損益にせず、純資産の部に直入します。翌期首には逆仕訳で洗い替えます。"}, {"q": "B社株式を1,200,000で取得し、決算時の時価は1,350,000でした(全部純資産直入法)。決算時と、翌期首の洗替えの仕訳を示しなさい。", "a": ["決算時:(借)その他有価証券 150,000 (貸)その他有価証券評価差額金 150,000", "翌期首:(借)その他有価証券評価差額金 150,000 (貸)その他有価証券 150,000"], "e": "評価差額=1,350,000−1,200,000=150,000です。評価差額は損益にせず、純資産の部に直入します。翌期首には逆仕訳で洗い替えます。"}], "3": [{"q": "売掛金3,000,000(うち甲社分400,000は貸倒懸念債権)と受取手形2,000,000があります。貸倒引当金の残高は40,000です。一般債権には1%の貸倒実績率を使い、甲社分は担保の評価額150,000を除いた残額の50%を見込みます。決算の仕訳を示しなさい。", "a": ["(借)貸倒引当金繰入 131,000 (貸)貸倒引当金 131,000"], "e": "一般債権=(5,000,000−400,000)×1%=46,000です。甲社分=(400,000−150,000)×50%=125,000です。合計171,000から、既存の残高40,000を引いた131,000を繰り入れます。"}, {"q": "売掛金1,500,000(うち甲社分200,000は貸倒懸念債権)と受取手形500,000があります。貸倒引当金の残高は20,000です。一般債権には3%の貸倒実績率を使い、甲社分は担保の評価額80,000を除いた残額の50%を見込みます。決算の仕訳を示しなさい。", "a": ["(借)貸倒引当金繰入 94,000 (貸)貸倒引当金 94,000"], "e": "一般債権=(2,000,000−200,000)×3%=54,000です。甲社分=(200,000−80,000)×50%=60,000です。合計114,000から、既存の残高20,000を引いた94,000を繰り入れます。"}], "4": [{"q": "商品500ドルを掛けで輸出しました(取引日のレートは1ドル120円)。決算日のレートは1ドル124円、翌期の決済日のレートは1ドル121円で、代金は当座預金に入金されました。(1)取引時、(2)決算時、(3)決済時の仕訳を示しなさい。", "a": ["(1)(借)売掛金 60,000 (貸)売上 60,000", "(2)(借)売掛金 2,000 (貸)為替差損益 2,000", "(3)(借)当座預金 60,500 (借)為替差損益 1,500 (貸)売掛金 62,000"], "e": "取引時=500ドル×120=60,000です。決算時は124円に換算し、差の2,000が為替差益です。決済時は121円で入金されるので、帳簿の62,000との差1,500が為替差損です。"}, {"q": "商品3,000ドルを掛けで輸出しました(取引日のレートは1ドル90円)。決算日のレートは1ドル92円、翌期の決済日のレートは1ドル91円で、代金は当座預金に入金されました。(1)取引時、(2)決算時、(3)決済時の仕訳を示しなさい。", "a": ["(1)(借)売掛金 270,000 (貸)売上 270,000", "(2)(借)売掛金 6,000 (貸)為替差損益 6,000", "(3)(借)当座預金 273,000 (借)為替差損益 3,000 (貸)売掛金 276,000"], "e": "取引時=3,000ドル×90=270,000です。決算時は92円に換算し、差の6,000が為替差益です。決済時は91円で入金されるので、帳簿の276,000との差3,000が為替差損です。"}], "5": [{"q": "中間納付した法人税等400,000(仮払法人税等)があり、決算で当期の法人税等が900,000と確定しました。また、貸倒引当金の繰入限度超過額が300,000あり(損金不算入)、法定実効税率は40%です。(1)法人税等の計上と(2)税効果の仕訳を示しなさい。", "a": ["(1)(借)法人税、住民税及び事業税 900,000 (貸)仮払法人税等 400,000 (貸)未払法人税等 500,000", "(2)(借)繰延税金資産 120,000 (貸)法人税等調整額 120,000"], "e": "未払法人税等=900,000−400,000=500,000です。繰延税金資産=300,000×40%=120,000で、将来の税金の前払いにあたります。"}, {"q": "中間納付した法人税等250,000(仮払法人税等)があり、決算で当期の法人税等が600,000と確定しました。また、貸倒引当金の繰入限度超過額が500,000あり(損金不算入)、法定実効税率は35%です。(1)法人税等の計上と(2)税効果の仕訳を示しなさい。", "a": ["(1)(借)法人税、住民税及び事業税 600,000 (貸)仮払法人税等 250,000 (貸)未払法人税等 350,000", "(2)(借)繰延税金資産 175,000 (貸)法人税等調整額 175,000"], "e": "未払法人税等=600,000−250,000=350,000です。繰延税金資産=500,000×35%=175,000で、将来の税金の前払いにあたります。"}], "6": [{"q": "(1)株式2,000株を1株1,200円で発行し、払込金は当座預金に入金されました(資本金は会社法が認める最低限度額とします)。\n(2)株主総会で、繰越利益剰余金から2,000,000の配当を決議しました(配当額の10分の1を利益準備金に積み立てます)。\n(3)当期純利益3,500,000を振り替えました。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)当座預金 2,400,000 (貸)資本金 1,200,000 (貸)資本準備金 1,200,000", "(2)(借)繰越利益剰余金 2,200,000 (貸)未払配当金 2,000,000 (貸)利益準備金 200,000", "(3)(借)損益 3,500,000 (貸)繰越利益剰余金 3,500,000"], "e": "払込額の2分の1までを資本金にしないことができ、残りは資本準備金です。配当を決議すると、配当額の10分の1(200,000)を利益準備金に積み立てます。当期純利益は損益勘定から繰越利益剰余金に振り替えます。"}, {"q": "(1)株式500株を1株4,000円で発行し、払込金は当座預金に入金されました(資本金は会社法が認める最低限度額とします)。\n(2)株主総会で、繰越利益剰余金から600,000の配当を決議しました(配当額の10分の1を利益準備金に積み立てます)。\n(3)当期純利益1,200,000を振り替えました。\nそれぞれの仕訳を示しなさい。", "a": ["(1)(借)当座預金 2,000,000 (貸)資本金 1,000,000 (貸)資本準備金 1,000,000", "(2)(借)繰越利益剰余金 660,000 (貸)未払配当金 600,000 (貸)利益準備金 60,000", "(3)(借)損益 1,200,000 (貸)繰越利益剰余金 1,200,000"], "e": "払込額の2分の1までを資本金にしないことができ、残りは資本準備金です。配当を決議すると、配当額の10分の1(60,000)を利益準備金に積み立てます。当期純利益は損益勘定から繰越利益剰余金に振り替えます。"}]}, "s3": {"0": [{"q": "期首商品120,000、当期仕入1,500,000です。期末の帳簿棚卸数量は300個(原価1個400円)、実地棚卸数量は285個、正味売却価額は1個380円です。売上原価を求める仕訳と、棚卸減耗損・商品評価損の仕訳を示しなさい(売上原価は「仕入」勘定で計算します)。", "a": ["(借)仕入 120,000 (貸)繰越商品 120,000", "(借)繰越商品 120,000 (貸)仕入 120,000", "(借)棚卸減耗損 6,000 (貸)繰越商品 6,000", "(借)商品評価損 5,700 (貸)繰越商品 5,700"], "e": "帳簿棚卸高=300×400=120,000。棚卸減耗損=(300−285)×400=6,000。商品評価損=(400−380)×285=5,700で、期末商品の貸借対照表価額は285×380=108,300です。"}, {"q": "期首商品50,000、当期仕入700,000です。期末の帳簿棚卸数量は100個(原価1個1,200円)、実地棚卸数量は96個、正味売却価額は1個1,140円です。売上原価を求める仕訳と、棚卸減耗損・商品評価損の仕訳を示しなさい(売上原価は「仕入」勘定で計算します)。", "a": ["(借)仕入 50,000 (貸)繰越商品 50,000", "(借)繰越商品 120,000 (貸)仕入 120,000", "(借)棚卸減耗損 4,800 (貸)繰越商品 4,800", "(借)商品評価損 5,760 (貸)繰越商品 5,760"], "e": "帳簿棚卸高=100×1,200=120,000。棚卸減耗損=(100−96)×1,200=4,800。商品評価損=(1,200−1,140)×96=5,760で、期末商品の貸借対照表価額は96×1,140=109,440です。"}], "1": [{"q": "決算日は3月31日です。\n(1)10月1日に年間家賃(12か月分)360,000を支払いました。前払分の仕訳を示しなさい。\n(2)12月1日に6,000,000を年利率4%(利払いは年1回の11月30日)で借り入れました。未払利息の仕訳を示しなさい。", "a": ["(1)(借)前払家賃 180,000 (貸)支払家賃 180,000", "(2)(借)支払利息 80,000 (貸)未払利息 80,000"], "e": "家賃は10/1〜9/30の12か月分で、決算日(3/31)までに6か月経過、残り6か月分=360,000×6÷12=180,000が前払いです。利息は12/1〜3/31の4か月分=6,000,000×4%×4÷12=80,000を見越計上します。"}, {"q": "決算日は3月31日です。\n(1)10月1日に年間家賃(12か月分)480,000を支払いました。前払分の仕訳を示しなさい。\n(2)12月1日に5,400,000を年利率5%(利払いは年1回の11月30日)で借り入れました。未払利息の仕訳を示しなさい。", "a": ["(1)(借)前払家賃 240,000 (貸)支払家賃 240,000", "(2)(借)支払利息 90,000 (貸)未払利息 90,000"], "e": "家賃は10/1〜9/30の12か月分で、決算日(3/31)までに6か月経過、残り6か月分=480,000×6÷12=240,000が前払いです。利息は12/1〜3/31の4か月分=5,400,000×5%×4÷12=90,000を見越計上します。"}], "2": [{"q": "取得原価2,000,000の備品(定額法、耐用年数10年、残存価額は取得原価の10%)の、当期の減価償却費と、前期末までに3年経過している場合の当期末の帳簿価額を求めなさい。", "a": ["当期の減価償却費 180,000", "当期末の帳簿価額 1,280,000"], "e": "年間償却額=2,000,000×(1−0.1)÷10=180,000。当期末の累計額=180,000×4年=720,000なので、帳簿価額=2,000,000−720,000=1,280,000です。"}, {"q": "取得原価1,500,000の備品(定額法、耐用年数5年、残存価額は取得原価の10%)の、当期の減価償却費と、前期末までに1年経過している場合の当期末の帳簿価額を求めなさい。", "a": ["当期の減価償却費 270,000", "当期末の帳簿価額 960,000"], "e": "年間償却額=1,500,000×(1−0.1)÷5=270,000。当期末の累計額=270,000×2年=540,000なので、帳簿価額=1,500,000−540,000=960,000です。"}], "3": [{"q": "試算表(一部)は、次のとおりです。\n・売上 6,000,000\n・仕入(当期分) 3,900,000\n・繰越商品(期首) 400,000\n・給料 900,000\n・支払家賃 360,000(10月1日に12か月分を支払い)\n・備品 2,000,000 / 備品減価償却累計額 400,000\n・売掛金 2,000,000 / 貸倒引当金 20,000\n決算整理は、(a)期末商品棚卸高500,000、(b)備品は定額法(耐用年数10年、残存価額ゼロ)、(c)貸倒引当金は売掛金残高の2%を設定(差額補充法)、(d)家賃の前払いを決算日3月31日で計上、(e)給料の未払いが60,000です。\n売上原価、売上総利益、営業利益、貸借対照表の備品(帳簿価額)と売掛金(貸倒引当金控除後)を求めなさい。", "a": ["売上原価 3,800,000", "売上総利益 2,200,000", "営業利益 840,000", "備品(帳簿価額) 1,400,000", "売掛金(貸倒引当金控除後) 1,960,000"], "e": "売上原価=400,000+3,900,000−500,000=3,800,000。売上総利益=6,000,000−3,800,000=2,200,000。販売費及び一般管理費=給料(900,000+60,000)+家賃(360,000−180,000)+減価償却費200,000(2,000,000÷10)+貸倒引当金繰入20,000(2,000,000×2%−20,000)=1,360,000。営業利益=2,200,000−1,360,000=840,000。備品の帳簿価額=2,000,000−(400,000+200,000)=1,400,000。売掛金=2,000,000−40,000=1,960,000。"}, {"q": "試算表(一部)は、次のとおりです。\n・売上 8,000,000\n・仕入(当期分) 5,000,000\n・繰越商品(期首) 600,000\n・給料 1,200,000\n・支払家賃 480,000(10月1日に12か月分を支払い)\n・備品 1,500,000 / 備品減価償却累計額 300,000\n・売掛金 1,500,000 / 貸倒引当金 10,000\n決算整理は、(a)期末商品棚卸高700,000、(b)備品は定額法(耐用年数6年、残存価額ゼロ)、(c)貸倒引当金は売掛金残高の4%を設定(差額補充法)、(d)家賃の前払いを決算日3月31日で計上、(e)給料の未払いが100,000です。\n売上原価、売上総利益、営業利益、貸借対照表の備品(帳簿価額)と売掛金(貸倒引当金控除後)を求めなさい。", "a": ["売上原価 4,900,000", "売上総利益 3,100,000", "営業利益 1,260,000", "備品(帳簿価額) 950,000", "売掛金(貸倒引当金控除後) 1,440,000"], "e": "売上原価=600,000+5,000,000−700,000=4,900,000。売上総利益=8,000,000−4,900,000=3,100,000。販売費及び一般管理費=給料(1,200,000+100,000)+家賃(480,000−240,000)+減価償却費250,000(1,500,000÷6)+貸倒引当金繰入50,000(1,500,000×4%−10,000)=1,840,000。営業利益=3,100,000−1,840,000=1,260,000。備品の帳簿価額=1,500,000−(300,000+250,000)=950,000。売掛金=1,500,000−60,000=1,440,000。"}], "4": [{"q": "(1)本店が支店に商品(原価)280,000を発送したとき、\n(2)支店が当期純利益120,000を計上し、本店に振り替えたとき\nの、本店と支店の仕訳をそれぞれ示しなさい。", "a": ["(1)本店:(借)支店 280,000 (貸)仕入 280,000", "(1)支店:(借)仕入 280,000 (貸)本店 280,000", "(2)支店:(借)損益 120,000 (貸)本店 120,000", "(2)本店:(借)支店 120,000 (貸)損益 120,000"], "e": "本店には「支店」勘定、支店には「本店」勘定を置き、貸借を逆にします。商品の発送では、本店が仕入を減らし、支店が仕入を増やします。支店の利益は本店の損益に入れます。"}, {"q": "(1)本店が支店に商品(原価)90,000を発送したとき、\n(2)支店が当期純利益45,000を計上し、本店に振り替えたとき\nの、本店と支店の仕訳をそれぞれ示しなさい。", "a": ["(1)本店:(借)支店 90,000 (貸)仕入 90,000", "(1)支店:(借)仕入 90,000 (貸)本店 90,000", "(2)支店:(借)損益 45,000 (貸)本店 45,000", "(2)本店:(借)支店 45,000 (貸)損益 45,000"], "e": "本店には「支店」勘定、支店には「本店」勘定を置き、貸借を逆にします。商品の発送では、本店が仕入を減らし、支店が仕入を増やします。支店の利益は本店の損益に入れます。"}], "5": [{"q": "決算時、本店の支店勘定は借方2,450,000、支店の本店勘定は貸方2,400,000でした。原因は、(a)本店が発送した商品80,000が支店に未達、(b)支店が本店の売掛金30,000を現金で回収したが、本店に未通知です。未達事項の整理仕訳(本店側・支店側)を示し、一致した残高を求めなさい。", "a": ["(a)支店:(借)仕入 80,000 (貸)本店 80,000", "(b)本店:(借)支店 30,000 (貸)売掛金 30,000", "一致した残高 2,480,000"], "e": "本店の支店勘定=2,450,000+30,000=2,480,000。支店の本店勘定=2,400,000+80,000=2,480,000。未達は、「自分がまだ知らない取引」を自分の帳簿に記入することです。"}, {"q": "決算時、本店の支店勘定は借方870,000、支店の本店勘定は貸方920,000でした。原因は、(a)本店が発送した商品40,000が支店に未達、(b)支店が本店の売掛金90,000を現金で回収したが、本店に未通知です。未達事項の整理仕訳(本店側・支店側)を示し、一致した残高を求めなさい。", "a": ["(a)支店:(借)仕入 40,000 (貸)本店 40,000", "(b)本店:(借)支店 90,000 (貸)売掛金 90,000", "一致した残高 960,000"], "e": "本店の支店勘定=870,000+90,000=960,000。支店の本店勘定=920,000+40,000=960,000。未達は、「自分がまだ知らない取引」を自分の帳簿に記入することです。"}]}, "s4": {"0": [{"q": "A社がB社を吸収合併し、新株を交付しました。B社の諸資産の時価は3,000,000、諸負債の時価は1,200,000です。交付した株式の時価は2,400,000で、そのうち資本金に1,500,000を計上し、残りは資本準備金とします。A社の仕訳を示しなさい(パーチェス法)。", "a": ["(借)諸資産 3,000,000 (借)のれん 600,000 (貸)諸負債 1,200,000 (貸)資本金 1,500,000 (貸)資本準備金 900,000"], "e": "純資産の時価=3,000,000−1,200,000=1,800,000。のれん=交付した株式の時価2,400,000−1,800,000=600,000です。交付した株式の時価を資本金と資本準備金に分けます。"}, {"q": "A社がB社を吸収合併し、新株を交付しました。B社の諸資産の時価は1,600,000、諸負債の時価は600,000です。交付した株式の時価は1,250,000で、そのうち資本金に800,000を計上し、残りは資本準備金とします。A社の仕訳を示しなさい(パーチェス法)。", "a": ["(借)諸資産 1,600,000 (借)のれん 250,000 (貸)諸負債 600,000 (貸)資本金 800,000 (貸)資本準備金 450,000"], "e": "純資産の時価=1,600,000−600,000=1,000,000。のれん=交付した株式の時価1,250,000−1,000,000=250,000です。交付した株式の時価を資本金と資本準備金に分けます。"}], "1": [{"q": "事業を現金2,400,000で譲り受けました。譲り受けた諸資産の時価は3,000,000、諸負債の時価は1,200,000です。仕訳を示しなさい。", "a": ["(借)諸資産 3,000,000 (借)のれん 600,000 (貸)諸負債 1,200,000 (貸)現金 2,400,000"], "e": "事業譲渡も、合併と同じ考え方です。のれん=支払対価2,400,000−1,800,000=600,000です。合併と違い、株式ではなく現金を払うので、貸方は現金になります。"}, {"q": "事業を現金1,250,000で譲り受けました。譲り受けた諸資産の時価は1,600,000、諸負債の時価は600,000です。仕訳を示しなさい。", "a": ["(借)諸資産 1,600,000 (借)のれん 250,000 (貸)諸負債 600,000 (貸)現金 1,250,000"], "e": "事業譲渡も、合併と同じ考え方です。のれん=支払対価1,250,000−1,000,000=250,000です。合併と違い、株式ではなく現金を払うので、貸方は現金になります。"}], "2": [{"q": "合併(または事業譲渡)で計上したのれん600,000を、取得から期末まで1年(期首に取得)、定額法12年で償却します。決算の仕訳を示しなさい。", "a": ["(借)のれん償却 50,000 (貸)のれん 50,000"], "e": "600,000÷12年=50,000です。のれんは無形固定資産として、直接法で記帳します。"}, {"q": "合併(または事業譲渡)で計上したのれん250,000を、取得から期末まで1年(期首に取得)、定額法5年で償却します。決算の仕訳を示しなさい。", "a": ["(借)のれん償却 50,000 (貸)のれん 50,000"], "e": "250,000÷5年=50,000です。のれんは無形固定資産として、直接法で記帳します。"}], "3": [{"q": "P社がS社の株式の70%を800,000で取得して支配しました。取得日のS社の純資産は資本金600,000、利益剰余金400,000で、資産・負債の時価と帳簿価額は同じです。連結修正仕訳(投資と資本の相殺消去)を示しなさい。", "a": ["(借)資本金 600,000 (借)利益剰余金 400,000 (借)のれん 100,000 (貸)S社株式 800,000 (貸)非支配株主持分 300,000"], "e": "S社の純資産=600,000+400,000=1,000,000。P社持分70%=700,000、のれん=800,000−700,000=100,000。非支配株主持分=1,000,000×30%=300,000です。借方と貸方の合計はどちらも1,100,000で一致します。"}, {"q": "P社がS社の株式の60%を1,080,000で取得して支配しました。取得日のS社の純資産は資本金1,000,000、利益剰余金500,000で、資産・負債の時価と帳簿価額は同じです。連結修正仕訳(投資と資本の相殺消去)を示しなさい。", "a": ["(借)資本金 1,000,000 (借)利益剰余金 500,000 (借)のれん 180,000 (貸)S社株式 1,080,000 (貸)非支配株主持分 600,000"], "e": "S社の純資産=1,000,000+500,000=1,500,000。P社持分60%=900,000、のれん=1,080,000−900,000=180,000。非支配株主持分=1,500,000×40%=600,000です。借方と貸方の合計はどちらも1,680,000で一致します。"}], "4": [{"q": "P社はS社の株式の70%を取得して支配し、のれん100,000を計上しています。その次の期で、\n(1)のれんを、取得から10年で定額法償却します。\n(2)S社の当期純利益は200,000です。\n(3)S社が100,000の配当を行い、P社はその70%を受け取りました。\nそれぞれの連結修正仕訳を示しなさい。", "a": ["(1)(借)のれん償却 10,000 (貸)のれん 10,000", "(2)(借)非支配株主に帰属する当期純利益 60,000 (貸)非支配株主持分 60,000", "(3)(借)受取配当金 70,000 (借)非支配株主持分 30,000 (貸)剰余金の配当 100,000"], "e": "のれん償却=100,000÷10=10,000。非支配株主の持分は30%なので、当期純利益200,000×30%=60,000。配当100,000のうち、P社分は70%の70,000(受取配当金)、非支配株主分は30%の30,000です。"}, {"q": "P社はS社の株式の60%を取得して支配し、のれん180,000を計上しています。その次の期で、\n(1)のれんを、取得から18年で定額法償却します。\n(2)S社の当期純利益は150,000です。\n(3)S社が80,000の配当を行い、P社はその60%を受け取りました。\nそれぞれの連結修正仕訳を示しなさい。", "a": ["(1)(借)のれん償却 10,000 (貸)のれん 10,000", "(2)(借)非支配株主に帰属する当期純利益 60,000 (貸)非支配株主持分 60,000", "(3)(借)受取配当金 48,000 (借)非支配株主持分 32,000 (貸)剰余金の配当 80,000"], "e": "のれん償却=180,000÷18=10,000。非支配株主の持分は40%なので、当期純利益150,000×40%=60,000。配当80,000のうち、P社分は60%の48,000(受取配当金)、非支配株主分は40%の32,000です。"}], "5": [{"q": "P社はS社に商品900,000を売り上げました。S社の期末商品には、このうち600,000が残っています。P社の売上総利益率は25%です。内部売上の相殺と、期末商品に含まれる未実現利益の消去の連結修正仕訳を示しなさい。", "a": ["(借)売上高 900,000 (貸)売上原価 900,000", "(借)売上原価 150,000 (貸)商品 150,000"], "e": "内部売上は、売上高と売上原価を同額で相殺します。未実現利益=期末商品600,000×25%=150,000で、P社が計上した利益なので、ダウンストリームでは全額を親会社株主が負担し、非支配株主には配分しません。"}, {"q": "P社はS社に商品800,000を売り上げました。S社の期末商品には、このうち500,000が残っています。P社の売上総利益率は10%です。内部売上の相殺と、期末商品に含まれる未実現利益の消去の連結修正仕訳を示しなさい。", "a": ["(借)売上高 800,000 (貸)売上原価 800,000", "(借)売上原価 50,000 (貸)商品 50,000"], "e": "内部売上は、売上高と売上原価を同額で相殺します。未実現利益=期末商品500,000×10%=50,000で、P社が計上した利益なので、ダウンストリームでは全額を親会社株主が負担し、非支配株主には配分しません。"}], "6": [{"q": "P社のS社に対する売掛金500,000(S社の買掛金500,000と同額)があり、P社はこの売掛金に対して1%の貸倒引当金を計上しています。連結修正仕訳を示しなさい。", "a": ["(借)買掛金 500,000 (貸)売掛金 500,000", "(借)貸倒引当金 5,000 (貸)貸倒引当金繰入 5,000"], "e": "債権と債務を同額で相殺し、その債権に設定した貸倒引当金(500,000×1%=5,000)も相殺します。"}, {"q": "P社のS社に対する売掛金800,000(S社の買掛金800,000と同額)があり、P社はこの売掛金に対して3%の貸倒引当金を計上しています。連結修正仕訳を示しなさい。", "a": ["(借)買掛金 800,000 (貸)売掛金 800,000", "(借)貸倒引当金 24,000 (貸)貸倒引当金繰入 24,000"], "e": "債権と債務を同額で相殺し、その債権に設定した貸倒引当金(800,000×3%=24,000)も相殺します。"}]}};
BOKI.forEach(function (u) { var v = BOKI_V[u.id]; if (v) u.ps.forEach(function (p, i) { if (v[i]) p.v = v[i]; }); });
